CREATE FUNCTION [dbo].[channelTypeF](@tip_kanala varchar(max), @primechanie varchar(max)) RETURNS int
BEGIN

DECLARE @k int

SET @k = CASE @tip_kanala
       when '1' then 4
       when '2' then 4
       when '3' then 4
       when '4' then 2
       when '5' then 1 -- Гильза
       when '6' then 7
       when '7' then 6
       when '9' then 5
       when '10' then 8  -- Футляр
       when '11' then 2
       when '12' then 9
       when '13' then 7
       when '14' then 4
       when 'Гильза' then 1
       when 'Ж/б блоки' then 2
       when 'ж/б канал' then 2
       when 'Кл' then  4
       when 'Короб' then 4
       when 'Разгрузочные плиты' then 9
       when 'Футляр' then 8
       else NULL
       end

IF @k IS NULL BEGIN
    SET @k = dbo.type_prim(@primechanie)
END

RETURN @k
END

GO

GO
