GO
CREATE function [dbo].[colList](@table_name nvarchar(max))       RETURNS nvarchar(max) begin   declare @ColList nvarchar(max);   SET @ColList = '';   SELECT @ColList = @ColList + Name + ', ' FROM syscolumns where id = object_id(@table_name) ;   SET @ColList = substring( @ColList, 1, (len( @ColList) - 1));   return @ColList; end; ;
GO

GO
SET QUOTED_IDENTIFIER ON
GO
CREATE function [dbo].[colListWithAdd2](@table_name nvarchar(max), @fl FieldList READONLY)  RETURNS nvarchar(max) begin DECLARE @qq NVARCHAR(max);  DECLARE @ColList NVARCHAR(max);  DECLARE @name NVARCHAR(max);  DECLARE @field_name NVARCHAR(max);  DECLARE @field_id INT;   DECLARE @CURSOR CURSOR  SET @ColList = ''; SET @CURSOR  = CURSOR SCROLL FOR SELECT Name FROM syscolumns where id = object_id(@table_name);  OPEN @CURSOR  FETCH NEXT FROM @CURSOR INTO @name  WHILE @@FETCH_STATUS = 0 BEGIN   SET @ColList = @ColList + @name;    DECLARE @CURSOR_FL CURSOR;    SET @CURSOR_FL = CURSOR SCROLL FOR SELECT DISTINCT field_name, field_id FROM @fl;    OPEN @CURSOR_FL;        FETCH NEXT FROM @CURSOR_FL INTO @field_name, @field_id;        WHILE @@FETCH_STATUS = 0    BEGIN       SET @ColList = @ColList + dbo.getAddField(@name, @field_name, @field_id);       FETCH NEXT FROM @CURSOR_FL INTO @field_name, @field_id;    END    CLOSE @CURSOR_FL;    DEALLOCATE @CURSOR_FL;   SET @ColList = @ColList + ',';      FETCH NEXT FROM @CURSOR INTO @name; END; CLOSE @CURSOR; SET @ColList = substring( @ColList, 1, (len( @ColList) - 1)); RETURN @ColList; END; ;
GO

GO
SET QUOTED_IDENTIFIER OFF
GO


CREATE FUNCTION [dbo].[constr_prim](@primechanie nvarchar(max)) RETURNS INT
BEGIN

IF @primechanie LIKE 'L=%' OR @primechanie LIKE 'L-%' BEGIN
RETURN 12 -- Лоток
END

IF @primechanie LIKE 'футляр%' BEGIN
RETURN dbo.constr_prim_futl(@primechanie)
END

IF @primechanie LIKE 'гильз%' OR @primechanie LIKE 'гиьз%' OR @primechanie LIKE 'труба в трубе'
BEGIN
RETURN dbo.constr_prim_gilza(@primechanie)
END

IF @primechanie LIKE 'разгруз%' OR @primechanie LIKE 'разг.%'  OR @primechanie LIKE 'разхгруз%' OR @primechanie LIKE 'Ргзгруз%' BEGIN
RETURN 13
END

IF @primechanie LIKE 'электр%' BEGIN
RETURN NULL
END

IF @primechanie LIKE '% ФБС%' BEGIN
RETURN 18
END

IF @primechanie LIKE 'Канал КЛ%' OR @primechanie LIKE 'к-л %' BEGIN
RETURN 24
END


IF @primechanie LIKE 'ж/б кана%' OR @primechanie LIKE 'жб кана%' OR @primechanie LIKE 'бет.канал%' OR @primechanie LIKE 'канал%' BEGIN
RETURN 12
END

IF @primechanie LIKE 'ж/б плита%' OR @primechanie LIKE '352,70 в плиты' BEGIN

RETURN 13
END

IF @primechanie LIKE '[0-9][0-9][0-9]' BEGIN
RETURN NULL
END

IF @primechanie LIKE '[0-9][0-9][0-9],[0-9][0-9]' BEGIN
RETURN NULL
END


IF @primechanie LIKE 'ж/б блок%' BEGIN
RETURN 14
END


IF @primechanie LIKE '%лотка%'  OR @primechanie LIKE '%лоток%' BEGIN
RETURN 12
END


IF @primechanie LIKE 'монолитный%' BEGIN
RETURN 15
END

IF @primechanie LIKE 'Монтажный%' BEGIN
RETURN NULL
END

IF @primechanie LIKE 'new_is%' BEGIN
RETURN NULL
END

IF @primechanie LIKE 'ДУ500' BEGIN
RETURN 44
END

IF @primechanie LIKE 'П16-15' BEGIN
RETURN NULL
END

IF @primechanie LIKE 'П22-15' BEGIN
RETURN NULL
END

IF @primechanie LIKE 'непроходной канал' BEGIN
RETURN NULL
END

IF @primechanie LIKE 'проходной' BEGIN
RETURN NULL
END

IF @primechanie LIKE 'ст 273' BEGIN
RETURN 31
END

IF @primechanie LIKE 'ст 530' BEGIN
RETURN 35
END

IF @primechanie LIKE 'ст.325' BEGIN
RETURN 32
END

IF @primechanie LIKE 'ст800' BEGIN
RETURN 38
END




IF @primechanie LIKE 'исп%' BEGIN
RETURN NULL
END

RETURN NULL
END

GO

GO
SET QUOTED_IDENTIFIER OFF
GO

CREATE FUNCTION [dbo].[constr_prim_futl](@primechanie nvarchar(max)) RETURNS INT
BEGIN

RETURN CASE @primechanie

when 'Футляр 1020' then 48
when 'Футляр 1220' then 49
when 'футляр 1220x14' then 49
when 'Футляр 1220х14' then 49
when 'Футляр 1420х14' then 52
when 'Футляр 219' then 50
when 'футляр 219    L=12.4м' then 50
when 'футляр 219 L=8м' then 50
when 'Футляр 273    L=13.1м' then 51
when 'Футляр 273  L=8м' then 51
when 'Футляр 273 L-20.8' then 51
when 'Футляр 273х9' then 51
when 'Футляр 2ДУ1020х14' then 48
when 'Футляр 325' then 42
when 'Футляр 325х9' then 42
when 'Футляр 426 L-49' then 43
when 'Футляр 530   L=10м' then 44
when 'Футляр L=27,8м' then NULL
when 'футляр L-39.2м' then NULL
when 'Футляр ДУ1420' then 52
when 'Футляр ст.325' then 42
when 'футляр ст.500' then 44
when 'Футляр ст.530 39,5м' then 44
when 'Футляр СТ.600' then 45
when 'Футляр ст.630' then 45
when 'Футляр ст.630  21м' then 45
when 'футляр ст.630  l=25,8м' then 45
when 'футляр ст.630  l=26,1м' then 45
when 'футляр ст.630 10,4м' then 45
when 'футляр ст.630 13,3м' then 45
when 'Футляр ст.630 14,6' then 45
when 'футляр ст.630 14,6м' then 45
when 'Футляр ст.630 14м' then 45
when 'Футляр ст.630 21м' then 45
when 'футляр ст.630 39,1м' then 45
when 'Футляр ст.630 48,7м' then 45
when 'футляр ст.630 l=12,4м' then 45
when 'Футляр ст.820' then 47
when 'Футляр ст.труба 2ДУ377х10         L=14м' then 42
when 'Футляр СТ1420х14' then 52
when 'Футляр ст600 L-52.7м' then 45
END

RETURN NULL
END

GO

GO
