CREATE FUNCTION [dbo].[dubl_d1](@sdiam varchar(max)) RETURNS float
BEGIN

DECLARE @sd1 varchar(max);
DECLARE @d1 INT;
DECLARE @n INT;

SET @sdiam = dbo.dubl_ispr_diam(@sdiam)

SET @d1 = dbo.dubl_spec_diam(@sdiam)
IF @d1 != -1 BEGIN
    RETURN @d1
END

SET @sdiam = REPLACE(@sdiam,',','.');

SET @n = charindex('/', @sdiam)

SET @sd1 = @sdiam

IF @n > 0 BEGIN
    SET @sd1 = substring(@sdiam, 1, @n-1)
END

IF @sd1 = NULL  BEGIN
    return 0
END


SET @d1 = CONVERT(float, @sd1)

RETURN @d1
END;

GO

GO
SET QUOTED_IDENTIFIER OFF
GO

CREATE FUNCTION [dbo].[dubl_d2](@sdiam varchar(max)) RETURNS float
BEGIN


DECLARE @sd1 varchar(max);
DECLARE @d1 INT;
DECLARE @n INT;

SET @sdiam = dbo.dubl_ispr_diam(@sdiam)

SET @d1 = dbo.dubl_spec_diam(@sdiam)
IF @d1 != -1 BEGIN
    RETURN @d1
END

SET @sdiam = REPLACE(@sdiam,',','.');

SET @n = charindex('/', @sdiam)

SET @sd1 = @sdiam

IF @n > 0 BEGIN
    SET @sd1 = substring(@sdiam, @n+1,  len(@sdiam))
END

IF @sd1 = NULL BEGIN
    return 0
END


SET @d1 = CONVERT(float, @sd1)

RETURN @d1
END;

GO

GO
SET QUOTED_IDENTIFIER OFF
GO



