CREATE FUNCTION [dbo].[getRusField] (@field varchar(max))
    RETURNS VARCHAR(max)
AS
begin
    declare @result varchar(1000)
    select @result = COALESCE(@result+','+A.rus_name, A.rus_name)
        FROM (  select  s.rus_name
                from (SELECT a.rus_name FROM fn_split_string(@field,',') sp
                left join (SELECT name, rus_name from listPtsTables) as a ON a.name = sp.value) s
        ) A
    return @result
end

