CREATE FUNCTION [dbo].[line2poly](@shape geometry) RETURNS geometry
BEGIN
DECLARE @lenp int = len('POINT (')
DECLARE @q varchar(max)
DECLARE @p1 varchar(max)  -- Первый узел
DECLARE @p2 varchar(max)  -- Последний узел
DECLARE @l1 varchar(max)
DECLARE @nl int

SET @shape = @shape.MakeValid()

IF @shape.STGeometryType () <> 'LineString' OR @shape.STNumCurves() <= 1 BEGIN
RETURN @shape
END

SET @nl = @shape.STNumCurves()

SET @l1 = @shape.STAsText()

SET @p1 = @shape.STPointN(1).STAsText()
SET @p1 = SUBSTRING(@p1, @lenp+1, len(@p1)-@lenp-1)

SET @p2 = @shape.STPointN(@nl+1).STAsText()
SET @p2 = SUBSTRING(@p2, @lenp+1, len(@p2)-@lenp-1)

SET @l1 = REPLACE(@l1, 'LINESTRING (', 'POLYGON ((')

IF @p1 = @p2 BEGIN
SET @l1 = CONCAT(@l1, ')')
END
ELSE BEGIN
SET @l1 = REPLACE(@l1, ')', ', ')
SET @l1 = CONCAT(@l1, @p1, '))')
END

SET @shape = geometry::STGeomFromText(@l1, 0)

RETURN @shape
END

GO

GO
SET QUOTED_IDENTIFIER OFF
GO


