CREATE FUNCTION [dbo].[remont_is_remont](@otchet_po_defektu varchar(max)) RETURNS INT
BEGIN

  RETURN
  IIF (
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Тек.ремонт%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Теущ.ремонт%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%кап.ремонт%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%кап ремонт%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Капитальный%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Инвестиции%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Инвест программа%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Реконструкция%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Замена%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Переукладка%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Переуклдака%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Увеличение диаметра%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%поднятие%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%перенос т/тр%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%монтаж т/тр%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Установка площадок обслуживания%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%замены%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Вынос т/тр%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Выынос горизонтального компенсатора на вертикальный%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Демонтаж П-образного компенсатора на ППУ%'
  OR
    CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Выполнено усиление т/тр%'
    , 1, 0)

END


GO

