CREATE FUNCTION [dbo].[remont_type_remont](@otchet_po_defektu varchar(max)) RETURNS INT
BEGIN
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Тек.ремонт%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Теущ.ремонт%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%кап.ремонт%' BEGIN
        RETURN 2
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%кап ремонт%' BEGIN
        RETURN 2
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Капитальный%' BEGIN
        RETURN 2
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Инвестиции%' BEGIN
        RETURN 1
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Инвест программа%' BEGIN
        RETURN 1
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Реконструкция%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Замена%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Переукладка%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Переуклдака%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Увеличение диаметра%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%поднятие%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%перенос т/тр%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%монтаж т/тр%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Установка площадок обслуживания%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%замены%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Вынос т/тр%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Выынос горизонтального компенсатора на вертикальный%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Демонтаж П-образного компенсатора на ППУ%' BEGIN
        RETURN 3
    END
    IF CONVERT(nvarchar(max),  @otchet_po_defektu) LIKE '%Выполнено усиление т/тр%' BEGIN
        RETURN 3
    END

    RETURN 3

END



