create function [dbo].[str_coords](
  @list varchar(8000)
) returns varchar(8000)

BEGIN

DECLARE @pos INT;
DECLARE @len INT;
DECLARE @len2 INT;

DECLARE @value varchar(8000);
DECLARE @value2 float;
DECLARE @limit varchar(10);
DECLARE @limit2 varchar(10);
DECLARE @zpt varchar(10);

DECLARE @out varchar(8000);
DECLARE @even INT;


-- SET @list = '24345 454365 43645 653456 243654 46345 '

set @limit = ' '
set @limit2 = ' '
set @zpt = ','

set @pos = 0
set @len = 0

set @out = ''
set @even = 0

IF @list = '' OR @list IS NULL BEGIN
  RETURN '';
END

-- select replace(@list,',', ' ')

set @list = @list + ' '



WHILE CHARINDEX(@limit, @list, @pos+1)>0
BEGIN
    set @len = CHARINDEX(@limit, @list, @pos+1) - @pos
--    set @len2 = CHARINDEX(@zpt, @list, @pos+1) - @pos

--    IF @len2 > 0 AND @len2 < @len BEGIN
--        set @len = @len2
--    END

    set @value = SUBSTRING(@list, @pos, @len)

    set @value2 = try_convert(float, @value)/100

--    PRINT @value2 -- for debug porpose


    set @pos = CHARINDEX(@limit, @list, @pos+@len) +1

  IF @even = 0 BEGIN
    set @even = 1
    set @limit2 = ','
  END
    ELSE BEGIN
    set @even = 0
    set @limit2 = ' '
    set @value2 = -@value2
  END

  IF @out = '' BEGIN
    set @out = @value2
  END
  ELSE BEGIN
    set @out = CONCAT(@out, @limit2, @value2)
  END

--    PRINT @out


END

  set @out = CONCAT(@out, ',')

  return @out
END


GO

GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE FUNCTION [dbo].[type_prim](@primechanie nvarchar(max)) RETURNS INT
BEGIN

IF @primechanie LIKE 'L=%' OR @primechanie LIKE 'L-%' BEGIN
RETURN 4 -- Лоток
END

IF @primechanie LIKE 'футляр%' BEGIN
RETURN 8
END

IF @primechanie LIKE 'гильз%' OR @primechanie LIKE 'гиьз%' OR @primechanie LIKE 'труба в трубе'
BEGIN
RETURN 1
END

IF @primechanie LIKE 'разгруз%' OR @primechanie LIKE 'разг.%'  OR @primechanie LIKE 'разхгруз%' OR @primechanie LIKE 'Ргзгруз%' BEGIN
RETURN 6
END

IF @primechanie LIKE 'электр%' BEGIN
RETURN NULL
END

IF @primechanie LIKE '% ФБС%' BEGIN
RETURN NULL
END

IF @primechanie LIKE 'Канал КЛ%' OR @primechanie LIKE 'к-л %' BEGIN
RETURN NULL
END


IF @primechanie LIKE 'ж/б кана%' OR @primechanie LIKE 'жб кана%' OR @primechanie LIKE 'бет.канал%' OR @primechanie LIKE 'канал%' BEGIN
RETURN NULL
END

IF @primechanie LIKE 'ж/б плита%' OR @primechanie LIKE '352,70 в плиты' BEGIN

RETURN NULL
END

IF @primechanie LIKE '[0-9][0-9][0-9]' BEGIN
RETURN NULL
END

IF @primechanie LIKE '[0-9][0-9][0-9],[0-9][0-9]' BEGIN
RETURN NULL
END


IF @primechanie LIKE 'ж/б блок%' BEGIN
RETURN NULL
END


IF @primechanie LIKE '%лотка%'  OR @primechanie LIKE '%лоток%'

BEGIN
RETURN 4
END


IF @primechanie LIKE 'монолитный%' BEGIN
RETURN 3
END

IF @primechanie LIKE 'Монтажный%' BEGIN
RETURN NULL
END

IF @primechanie LIKE 'new_is%' BEGIN
RETURN NULL
END

IF @primechanie LIKE 'ДУ%' BEGIN
RETURN 8
END

IF @primechanie LIKE 'П16-15' BEGIN
RETURN NULL
END

IF @primechanie LIKE 'П22-15' BEGIN
RETURN NULL
END

IF @primechanie LIKE 'непроходной канал' BEGIN
RETURN 7
END

IF @primechanie LIKE 'проходной' BEGIN
RETURN 5
END

IF @primechanie LIKE 'ст.%' OR @primechanie LIKE 'ст%' BEGIN
RETURN 1
END

IF @primechanie LIKE 'исп%' BEGIN
RETURN NULL
END

RETURN NULL
END

GO

