CREATE VIEW [dbo].[vt_pipe_laying_sources] AS

(SELECT
IIF(hst.name is NULL, 1, 0) as flag,
IIF(l.externalSignLineID IN (1,2,4),  hps.pipeSectLength, 0) AS lenP,
IIF(l.externalSignLineID IN (1,3,5),  hps.pipeSectLength, 0) AS lenO,
hs.sourceName as hs_name,
hst.name as hst_name,
n1.fileID

FROM heatPipeSections hps
left JOIN linesobj l ON hps.lineID=l.id
left JOIN nodes n1 ON n1.id=l.nodeID1
left JOIN nodes n2 ON n2.id=l.nodeID2

left join externalCodes ec1 ON ec1.id = n1.externalCodeID
left join externalCodes ec2 ON ec2.id = n2.externalCodeID

left join heatSources hs ON hs.id = ec1.heatSourceID
left join heatSourceTypes hst ON hst.id = hs.hSourceTypeID
WHERE l.removed = 0
        AND not l.shape is null
        AND (n1.internalNodeID IS NULL and n2.internalNodeID is NULL)
        AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
        AND (n1.removed=0 and n2.removed=0)
        AND ec1.id != ec2.id
)

UNION ALL

(SELECT
IIF(hst.name is NULL, 1, 0) as flag,
IIF(l.externalSignLineID IN (1,2,4),  hps.pipeSectLength, 0) AS lenP,
IIF(l.externalSignLineID IN (1,3,5),  hps.pipeSectLength, 0) AS lenO,
hs.sourceName as hs_name,
hst.name as hst_name,
n1.fileID

FROM heatPipeSections hps
left JOIN linesobj l ON hps.lineID=l.id
left JOIN nodes n1 ON n1.id=l.nodeID1
left JOIN nodes n2 ON n2.id=l.nodeID2
left join externalCodes ec1 ON ec1.id = n1.externalCodeID
left join externalCodes ec2 ON ec2.id = n2.externalCodeID

left join heatSources hs ON hs.id = ec2.heatSourceID
left join heatSourceTypes hst ON hst.id = hs.hSourceTypeID
WHERE l.removed = 0
        AND not l.shape is null
        AND (n1.internalNodeID IS NULL and n2.internalNodeID is NULL)
        AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
        AND (n1.removed=0 and n2.removed=0)
        AND ec1.id = ec2.id
)

