CREATE FUNCTION [dbo].[getRealConsumersNagruzkiByHeatPointID] ()
RETURNS TABLE
AS
RETURN

(

    select sum(t.CO) as raschetnayaNagruzkaCO,

        sum(t.avgGV) as srednyayaNagruzkaGV,

        sum(t.maxGV) as maxNagruzkaGV,

        sum(t.SV) as raschetnayaNagruzkaSV,

        sum(t.countUserGV) as countUserGV,

        sum(t.countBusinessConsumers) as countBusinessConsumers,

        sum(t.area) as area,

        sum(t.buildingVolume) as buildingVolume,

        sum(t.basementVolume) as basementVolume,

        sum(t.builtInVolume)    as builtInVolume,

        t.heatPointID

    from (

        select

            id,

            name,

            CASE

                WHEN  PATINDEX('1.[5-6]',schemeNum) > 0 OR PATINDEX('%.9',schemeNum) > 0 OR PATINDEX('%.1[0-2]',schemeNum) > 0  THEN  calcHLindep 

                WHEN  PATINDEX('1.[1-4]',schemeNum) > 0 OR PATINDEX('%.[5-8]',schemeNum) > 0 THEN  calcHLdep 

            END as CO,

            CASE

                WHEN PATINDEX('3.%',schemeNum) > 0 THEN avgHLGVScloseParall

                WHEN PATINDEX('4.%',schemeNum) > 0 THEN avgHLGVScloseMix

                WHEN PATINDEX('5.%',schemeNum) > 0 THEN avgHLGVScloseConseq

                WHEN PATINDEX('6.%',schemeNum) > 0 THEN avgHLGVSopenFlow

                WHEN PATINDEX('7.%',schemeNum) > 0 THEN avgHLGVSopenRet

                WHEN PATINDEX('15.%',schemeNum) > 0 THEN avgHLGVSclosePreON

            END as avgGV,

            CASE

                WHEN automDegID = 2 and PATINDEX('3.%',schemeNum) > 0 THEN avgHLGVScloseParall * hourIrregCoeff

                WHEN automDegID = 2 and PATINDEX('4.%',schemeNum) > 0 THEN avgHLGVScloseMix * hourIrregCoeff

                WHEN automDegID = 2 and PATINDEX('5.%',schemeNum) > 0 THEN avgHLGVScloseConseq * hourIrregCoeff

                WHEN automDegID = 2 and PATINDEX('6.%',schemeNum) > 0 THEN avgHLGVSopenFlow * hourIrregCoeff

                WHEN automDegID = 2 and PATINDEX('7.%',schemeNum) > 0 THEN avgHLGVSopenRet * hourIrregCoeff

                WHEN automDegID = 2 and PATINDEX('15.%',schemeNum) > 0 THEN avgHLGVSclosePreON * hourIrregCoeff

                WHEN automDegID = 1 and PATINDEX('3.%',schemeNum) > 0 THEN avgHLGVScloseParall * hourIrregCoeff

                WHEN automDegID = 1 and PATINDEX('4.%',schemeNum) > 0 THEN avgHLGVScloseMix * hourIrregCoeff

                WHEN automDegID = 1 and PATINDEX('5.%',schemeNum) > 0 THEN avgHLGVScloseConseq * hourIrregCoeff

                WHEN automDegID = 1 and PATINDEX('6.%',schemeNum) > 0 THEN avgHLGVSopenFlow * hourIrregCoeff

                WHEN automDegID = 1 and PATINDEX('7.%',schemeNum) > 0 THEN avgHLGVSopenRet * hourIrregCoeff

                WHEN automDegID = 1 and PATINDEX('15.%',schemeNum) > 0 THEN avgHLGVSclosePreON * hourIrregCoeff

            END as maxGV,

            calcHLventil as SV,

            countUserGV,

            countBusinessConsumers,

            area,

            buildingVolume,

            basementVolume,

            builtInVolume,

            heatPointID

        from realConsumers
    ) t
    --where t.heatPointID in (14)
    group by t.heatPointID
);

GO

GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[getRealConsumersNagruzkiNotSumByHeatPointID] (@id int, @type varchar(20))

RETURNS TABLE

AS

RETURN

(

    select
            rc.id,
            rc.name as 'Содержательное наименование потребителя',
            rc.contractNumber as 'Номер договора',
            st.name as 'Улица',
            rc.houseNumber as 'Номер дома',
            meter.name as 'Наличие счетчика',
            rc.countFloors as 'Кол-во этажей',
            rc.builtYear as 'Год постройки',
            hp.name as 'Наименование теплового пункта',
            rc.countUserGV as 'Число пользователей ГВ, чел',
            rc.countBusinessConsumers as 'Количество потребителей-предприятий, шт',
            CASE
                WHEN  PATINDEX('1.[1-4]',schemeNum) > 0 OR PATINDEX('%.[5-8]',schemeNum) > 0 THEN  calcHLdep 
                WHEN  PATINDEX('1.[5-6]',schemeNum) > 0 OR PATINDEX('%.9',schemeNum) > 0 OR PATINDEX('%.1[0-2]',schemeNum) > 0  THEN  calcHLindep 
            END as 'Расчётная нагрузка на CO, гкал/час',
            CASE
                WHEN PATINDEX('3.%',schemeNum) > 0 THEN avgHLGVScloseParall
                WHEN PATINDEX('4.%',schemeNum) > 0 THEN avgHLGVScloseMix
                WHEN PATINDEX('5.%',schemeNum) > 0 THEN avgHLGVScloseConseq
                WHEN PATINDEX('6.%',schemeNum) > 0 THEN avgHLGVSopenFlow
                WHEN PATINDEX('7.%',schemeNum) > 0 THEN avgHLGVSopenRet
                WHEN PATINDEX('15.%',schemeNum) > 0 THEN avgHLGVSclosePreON
            END as 'Средняя нагрузка на ГВ, гкал/час',
            CASE
                WHEN automDegID = 2 and PATINDEX('3.%',schemeNum) > 0 THEN avgHLGVScloseParall * hourIrregCoeff
                WHEN automDegID = 2 and PATINDEX('4.%',schemeNum) > 0 THEN avgHLGVScloseMix * hourIrregCoeff
                WHEN automDegID = 2 and PATINDEX('5.%',schemeNum) > 0 THEN avgHLGVScloseConseq * hourIrregCoeff
                WHEN automDegID = 2 and PATINDEX('6.%',schemeNum) > 0 THEN avgHLGVSopenFlow * hourIrregCoeff
                WHEN automDegID = 2 and PATINDEX('7.%',schemeNum) > 0 THEN avgHLGVSopenRet * hourIrregCoeff
                WHEN automDegID = 2 and PATINDEX('15.%',schemeNum) > 0 THEN avgHLGVSclosePreON * hourIrregCoeff
                WHEN automDegID = 1 and PATINDEX('3.%',schemeNum) > 0 THEN avgHLGVScloseParall * hourIrregCoeff
                WHEN automDegID = 1 and PATINDEX('4.%',schemeNum) > 0 THEN avgHLGVScloseMix * hourIrregCoeff
                WHEN automDegID = 1 and PATINDEX('5.%',schemeNum) > 0 THEN avgHLGVScloseConseq * hourIrregCoeff
                WHEN automDegID = 1 and PATINDEX('6.%',schemeNum) > 0 THEN avgHLGVSopenFlow * hourIrregCoeff
                WHEN automDegID = 1 and PATINDEX('7.%',schemeNum) > 0 THEN avgHLGVSopenRet * hourIrregCoeff
                WHEN automDegID = 1 and PATINDEX('15.%',schemeNum) > 0 THEN avgHLGVSclosePreON * hourIrregCoeff
            END as 'Максимальная нагрузка на ГВ, гкал/час',
            rc.calcHLventil as 'Расчётная нагрузка на СВ',
            rc.area as 'Отапливаемая площадь, м2',
            rc.buildingVolume  as 'Объем отапливаемого здания, м3',
            rc.basementVolume as 'Объем подвала отапливаемого здания, м3',
            rc.builtInVolume as 'Объем встроенных помещений отапливаемого здания, м3'
        from realConsumers rc
        join heatPoint hp on hp.id = rc.heatPointID
        left join nodes n ON n.id = rc.nodeID
        left join WEmeteringDevices meter on meter.id = rc.WEmeteringDeviceID
        left join streets st ON st.id = rc.streetID
        WHERE
            n.fileID != 122 and (
            (@type != 'all' and rc.heatPointID = @id) or (@type = 'all')
        )
)
GO

GO
