CREATE PROCEDURE [dbo].[copyDB] (   @fromDB nvarchar(max),   @toDB nvarchar(max),   @fileID0 INT ) AS BEGIN   DECLARE @fileID INT;    DECLARE @nodeID INT;    DECLARE @lineID INT;    DECLARE @calcTemperatureID INT;   DECLARE @gvsLoadGraphID    INT;   DECLARE @specExpendID      INT;   DECLARE @varCoefficientID  INT;   DECLARE @directionID       INT;   DECLARE @heatSourceID      INT;   DECLARE @fileIDe1 nvarchar(max);    DECLARE @IDe1 nvarchar(max);    DECLARE @externalCodeID INT;    declare @q nvarchar(max);   declare @e1 nvarchar(max);   DECLARE @IDlist FieldList;   DECLARE @fileIDlist FieldList;   SET @e1  = '=' + CAST(@fileID0 AS nvarchar);    SET @fileIDe1  = 'fileID' + @e1;    SET @IDe1  = 'ID' + @e1;    exec dbo.get_last_id 'fragments', @fileID OUTPUT;   exec dbo.get_last_id 'nodes', @nodeID OUTPUT;   exec dbo.get_last_id 'linesobj', @lineID OUTPUT;   exec dbo.get_last_id 'externalCodes', @externalCodeID OUTPUT;   exec dbo.get_last_id 'calcTemperatures', @calcTemperatureID OUTPUT;   exec dbo.get_last_id 'gvsLoadGraphs'   , @gvsLoadGraphID    OUTPUT;   exec dbo.get_last_id 'specExpends'     , @specExpendID      OUTPUT;   exec dbo.get_last_id 'varCoefficients' , @varCoefficientID  OUTPUT;   exec dbo.get_last_id 'directions'      , @directionID       OUTPUT;   exec dbo.get_last_id 'heatSources'      , @heatSourceID     OUTPUT;   INSERT @IDlist VALUES ('ID', @fileID);   exec dbo.copyDB2 @fromDB,  @toDB,  'fragments',   @IDe1,  @IDlist;   INSERT @fileIDlist VALUES ('fileID', @fileID)   INSERT @fileIDlist VALUES ('heatSourceID', @heatSourceID);   exec dbo.copyDB2 @fromDB,  @toDB,  'calcTemperatures', @fileIDe1, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'externalCodes',    @fileIDe1, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'gvsLoadGraphs',    @fileIDe1, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'specExpends',      @fileIDe1, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'varCoefficients',  @fileIDe1, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'directions',       @fileIDe1, @fileIDlist;   INSERT @fileIDlist VALUES ('externalCodeID', @externalCodeID);   INSERT @fileIDlist VALUES ('internalNodeID', @nodeID);   exec dbo.copyDB2 @fromDB,  @toDB,  'nodes',            @fileIDe1, @fileIDlist;   INSERT @fileIDlist VALUES ('nodeID', @nodeID);   INSERT @fileIDlist VALUES ('connectID', @nodeID);   INSERT @fileIDlist VALUES ('nodeID1', @nodeID);   INSERT @fileIDlist VALUES ('nodeID2', @nodeID);   INSERT @fileIDlist VALUES ('lineID', @lineID);   INSERT @fileIDlist VALUES ('calcTemperatureID', @calcTemperatureID);   INSERT @fileIDlist VALUES ('gvsLoadGraphID'   , @gvsLoadGraphID   );   INSERT @fileIDlist VALUES ('specExpendID'     , @specExpendID     );   INSERT @fileIDlist VALUES ('varCoeffID'       , @varCoefficientID );   INSERT @fileIDlist VALUES ('varCoeffIDflow'   , @varCoefficientID );   INSERT @fileIDlist VALUES ('varCoeffIDret'    , @varCoefficientID );   INSERT @fileIDlist VALUES ('directionID'      , @directionID      );   SET @q = 'nodeID1 IN (SELECT ID FROM ' + @fromDB + '.dbo.nodes WHERE ' + @fileIDe1 + ')';   exec dbo.copyDB2 @fromDB,  @toDB,  'linesobj', @q, @fileIDlist;   SET @q = 'nodeID IN (SELECT ID FROM ' + @fromDB + '.dbo.nodes WHERE ' + @fileIDe1 + ')';   exec dbo.copyDB2 @fromDB,  @toDB,  'setPressNodes', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'generalizedConsumers', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'heatChambers', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'heatSources', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'internalNodes', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'overgroundNodes', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'passports', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'pavilions', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'pumpStations', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'realConsumers', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'refillNodes', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'threeWayValves', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'trps', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'undergroundNodes', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'uninstalledNodes', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'WDOdevices', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'connectNodes', @q, @fileIDlist;   SET @q = 'directionID IN (SELECT ID FROM ' + @fromDB+'.dbo.directions WHERE ' + @fileIDe1 + ')';   exec dbo.copyDB2 @fromDB,  @toDB,  'deployedDirections',         @q, @fileIDlist;   SET @q = 'hSourceID IN (SELECT ID FROM ' + @fromDB+'.dbo.heatSources WHERE nodeID IN (SELECT ID FROM ' + @fromDB + '.dbo.nodes WHERE ' + @fileIDe1 + '))';   exec dbo.copyDB2 @fromDB,  @toDB,  'deployedTempGraphs',         @q, @fileIDlist;   SET @q = 'lineID IN (SELECT ID FROM ' + @fromDB+'.dbo.linesobj WHERE nodeID1 IN (SELECT ID FROM ' + @fromDB + '.dbo.nodes WHERE ' + @fileIDe1 + '))';   exec dbo.copyDB2 @fromDB,  @toDB,  'bypass', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'consumptRegulators', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'pressDropRegulators', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'pressRegulators', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'regulArmatures', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'airHeaters', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'dampers', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'diaphragms', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'elevators', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'heatExchangers', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'heatPipeSections', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'localHydroResistances2', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'pumps', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'reverseValves', @q, @fileIDlist;   exec dbo.copyDB2 @fromDB,  @toDB,  'systemRadiators', @q, @fileIDlist; END; ;
