CREATE PROC [dbo].[copyDB1](@fromDB nvarchar(max),  @toDB nvarchar(max),  @table_name nvarchar(max),  @param nvarchar(max), @fl FieldList READONLY) AS begin   DECLARE @insertQueries nvarchar(max);   DECLARE @a nvarchar(max);   DECLARE @ID INT;    exec dbo.get_last_id @table_name, @ID OUTPUT;   SET @insertQueries = dbo.copyDBText2(@fromDB, @toDB,  @table_name,  @param, @fl);   print(@insertQueries);   set @a = 'SET IDENTITY_INSERT ' + @toDB + '.dbo.' + @table_name + ' ON; ' +  @insertQueries + '; SET IDENTITY_INSERT ' + @toDB + '.dbo.' + @table_name + ' OFF; ' ;   exec (@a);   end; ;
GO

