CREATE PROCEDURE [dbo].[get_last_id] (@table_name0  nvarchar(max), @last_id INT OUTPUT) AS DECLARE @table_name NVARCHAR(max);  DECLARE @col_name NVARCHAR(max); DECLARE @next_id INT;  DECLARE @CURSOR CURSOR  SET @CURSOR  = CURSOR SCROLL FOR   select     OBJECT_NAME(object_id) as table_name     , name as col_name     , ISNULL(CAST(last_value AS INT), 0)+1 AS next_id   from      sys.identity_columns    WHERE      OBJECT_NAME(object_id)=@table_name0  OPEN @CURSOR  FETCH NEXT FROM @CURSOR INTO @table_name, @col_name, @next_id  WHILE @@FETCH_STATUS = 0 BEGIN SET @last_id = @next_id   FETCH NEXT FROM @CURSOR INTO @table_name, @col_name, @next_id END CLOSE @CURSOR; ;
GO

