CREATE TRIGGER [dbo].[externalCodes_UPDATE_heatSourcePTSID]
ON [dbo].[externalCodes]
AFTER UPDATE
AS
    UPDATE nrc
    set heatSourcePTSID = ec.heatSourceID
    from realConsumers nrc
    join nodes n1 ON n1.id=nrc.nodeID
    join externalCodes ec on ec.id = n1.externalCodeID AND ec.id IN ( SELECT id FROM inserted )
GO
