CREATE TRIGGER [dbo].[NODES_EDIT_EXTERNALCODES_FOR_INTERNALNODEID_AFTER_UPDATE]
ON [dbo].[nodes]

AFTER UPDATE
AS

IF EXISTS (SELECT *

           FROM DELETED d

           JOIN inserted i

           ON i.id = d.id

           WHERE i.externalCodeID != d.externalCodeID

          )
BEGIN

    DECLARE @externalCodeID_current INT, @current_nodeID INT;

    SET @externalCodeID_current = ( SELECT externalCodeID FROM inserted )

    SET @current_nodeID = ( SELECT id FROM inserted )

    UPDATE n
        set
            externalCodeID = @externalCodeID_current
        from nodes n
        where n.internalNodeID = @current_nodeID

END

GO
ALTER TABLE [dbo].[nodes] ENABLE TRIGGER [NODES_EDIT_EXTERNALCODES_FOR_INTERNALNODEID_AFTER_UPDATE]
GO

GO
