ON [dbo].[nodes]
AFTER UPDATE
AS

    UPDATE nrc
    set heatSourcePTSID = ec.heatSourceID
    from realConsumers nrc
    join nodes n1 ON n1.id=nrc.nodeID AND n1.id IN ( SELECT id FROM inserted )
    join externalCodes ec on ec.id  = n1.externalCodeID
GO
