CREATE TRIGGER [dbo].[PipeSections_UPDATE]
ON [dbo].[pipeSections]
AFTER UPDATE
AS
IF EXISTS (SELECT *
           FROM DELETED d
           JOIN inserted i
           ON i.id = d.id
           WHERE
                ( i.inventNumber <> d.inventNumber OR ( d.inventNumber is NULL and i.inventNumber is not NULL) ) OR
                ( i.objectTypeID <> d.objectTypeID OR ( d.objectTypeID is NULL and i.objectTypeID is not NULL) ) OR
                ( i.Sreda <> d.Sreda OR ( d.Sreda is NULL and i.Sreda is not NULL) ) OR
                ( i.press <> d.press OR ( d.press is NULL and i.press is not NULL) ) OR
                ( i.temperature <> d.temperature OR ( d.temperature is NULL and i.temperature is not NULL) ) OR
                ( i.SpokSluzhbiRash <> d.SpokSluzhbiRash OR ( d.SpokSluzhbiRash is NULL and i.SpokSluzhbiRash is not NULL) ) OR
                ( i.ressurs <> d.ressurs OR ( d.ressurs is NULL and i.ressurs is not NULL) ) OR
                ( i.pusk <> d.pusk OR ( d.pusk is NULL and i.pusk is not NULL) ) OR
                ( i.organizationID <> d.organizationID OR ( d.organizationID is NULL and i.organizationID is not NULL) ) OR
                ( i.Elektrich <> d.Elektrich OR ( d.Elektrich is NULL and i.Elektrich is not NULL) ) OR
                ( i.TransportElekricht <> d.TransportElekricht OR ( d.TransportElekricht is NULL and i.TransportElekricht is not NULL) ) OR
                ( i.Ponezial <> d.Ponezial OR ( d.Ponezial is NULL and i.Ponezial is not NULL) ) OR
                ( i.floodIntensityGWid <> d.floodIntensityGWid OR ( d.floodIntensityGWid is NULL and i.floodIntensityGWid is not NULL) ) OR
                ( i.floodIntensityFWid <> d.floodIntensityFWid OR ( d.floodIntensityFWid is NULL and i.floodIntensityFWid is not NULL) ) OR
                ( i.floodIntensityTWid <> d.floodIntensityTWid OR ( d.floodIntensityTWid is NULL and i.floodIntensityTWid is not NULL) ) OR
                ( i.floodIntensityBWid <> d.floodIntensityBWid OR ( d.floodIntensityBWid is NULL and i.floodIntensityBWid is not NULL) ) OR
                ( i.Vodootved <> d.Vodootved OR ( d.Vodootved is NULL and i.Vodootved is not NULL) ) OR
                ( i.SlozhOkluzh <> d.SlozhOkluzh OR ( d.SlozhOkluzh is NULL and i.SlozhOkluzh is not NULL) ) OR
                ( i.OtkluzhGkal <> d.OtkluzhGkal OR ( d.OtkluzhGkal is NULL and i.OtkluzhGkal is not NULL) ) OR
                ( i.AvariiVipoln <> d.AvariiVipoln OR ( d.AvariiVipoln is NULL and i.AvariiVipoln is not NULL) ) OR
                ( i.Pesehod <> d.Pesehod OR ( d.Pesehod is NULL and i.Pesehod is not NULL) ) OR
                ( i.ZhdDorogi <> d.ZhdDorogi OR ( d.ZhdDorogi is NULL and i.ZhdDorogi is not NULL) ) OR
                ( i.LudiProklad <> d.LudiProklad OR ( d.LudiProklad is NULL and i.LudiProklad is not NULL) ) OR
                ( i.UzherbLudi <> d.UzherbLudi OR ( d.UzherbLudi is NULL and i.UzherbLudi is not NULL) ) OR
                ( i.UzherbSity <> d.UzherbSity OR ( d.UzherbSity is NULL and i.UzherbSity is not NULL) ) OR
                ( i.VnesniiVid <> d.VnesniiVid OR ( d.VnesniiVid is NULL and i.VnesniiVid is not NULL) ) OR
                ( i.SostOborudovania <> d.SostOborudovania OR ( d.SostOborudovania is NULL and i.SostOborudovania is not NULL) ) OR
                ( i.VnesnKorrozia <> d.VnesnKorrozia OR ( d.VnesnKorrozia is NULL and i.VnesnKorrozia is not NULL) ) OR
                ( i.VnunrenKorrozia <> d.VnunrenKorrozia OR ( d.VnunrenKorrozia is NULL and i.VnunrenKorrozia is not NULL) ) OR
                ( i.SostKonstrukz <> d.SostKonstrukz OR ( d.SostKonstrukz is NULL and i.SostKonstrukz is not NULL) ) OR
                ( i.Kategorii <> d.Kategorii OR ( d.Kategorii is NULL and i.Kategorii is not NULL) )
            )
BEGIN

UPDATE hp
    set
        inventNumber =i.inventNumber,
        objectTypeID=i.objectTypeID,
        Sreda=i.Sreda,
        press=i.press,
        temperature=i.temperature,
        SpokSluzhbiRash=i.SpokSluzhbiRash,
        ressurs=i.ressurs,
        pusk=i.pusk,
        organizationID=i.organizationID,
        Elektrich=i.Elektrich,
        TransportElekricht=i.TransportElekricht,
        Ponezial=i.Ponezial,
        floodIntensityGWid=i.floodIntensityGWid,
        floodIntensityFWid=i.floodIntensityFWid,
        floodIntensityTWid=i.floodIntensityTWid,
        floodIntensityBWid=i.floodIntensityBWid,
        Vodootved=i.Vodootved,
        SlozhOkluzh=i.SlozhOkluzh,
        OtkluzhGkal=i.OtkluzhGkal,
        AvariiVipoln=i.AvariiVipoln,
        Pesehod=i.Pesehod,
        ZhdDorogi=i.ZhdDorogi,
        LudiProklad=i.LudiProklad,
        UzherbLudi=i.UzherbLudi,
        UzherbSity=i.UzherbSity,
        VnesniiVid=i.VnesniiVid,
        SostOborudovania=i.SostOborudovania,
        VnesnKorrozia=i.VnesnKorrozia,
        VnunrenKorrozia=i.VnunrenKorrozia,
        SostKonstrukz=i.SostKonstrukz,
        Kategorii=i.Kategorii
    from heatPipeSections hp
    join inserted i on i.id = hp.pipeSectionID

END
GO
ALTER TABLE [dbo].[pipeSections] ENABLE TRIGGER [PipeSections_UPDATE]
GO

