CREATE TRIGGER [dbo].[HeatPointCalc_UPDATE]
ON [dbo].[realConsumers]
AFTER UPDATE
AS
IF EXISTS (SELECT *
           FROM DELETED d
           JOIN inserted i
           ON i.id = d.id
           WHERE
                ( i.calcHLindep <> d.calcHLindep OR ( d.calcHLindep is NULL and i.calcHLindep is not NULL) ) OR
                ( i.calcHLdep <> d.calcHLdep OR ( d.calcHLdep is NULL and i.calcHLdep is not NULL) ) OR
                ( i.schemeNum <> d.schemeNum OR ( d.schemeNum is NULL and i.schemeNum is not NULL) ) OR
                ( i.avgHLGVScloseParall <> d.avgHLGVScloseParall OR ( d.avgHLGVScloseParall is NULL and i.avgHLGVScloseParall is not NULL) ) OR
                ( i.avgHLGVScloseMix <> d.avgHLGVScloseMix OR ( d.avgHLGVScloseMix is NULL and i.avgHLGVScloseMix is not NULL) ) OR
                ( i.avgHLGVScloseConseq <> d.avgHLGVScloseConseq OR ( d.avgHLGVScloseConseq is NULL and i.avgHLGVScloseConseq is not NULL) ) OR
                ( i.avgHLGVSopenFlow <> d.avgHLGVSopenFlow OR ( d.avgHLGVSopenFlow is NULL and i.avgHLGVSopenFlow is not NULL) ) OR
                ( i.avgHLGVSopenRet <> d.avgHLGVSopenRet OR ( d.avgHLGVSopenRet is NULL and i.avgHLGVSopenRet is not NULL) ) OR
                ( i.avgHLGVSclosePreON <> d.avgHLGVSclosePreON OR ( d.avgHLGVSclosePreON is NULL and i.avgHLGVSclosePreON is not NULL) ) OR
                ( i.calcHLventil <> d.calcHLventil OR ( d.calcHLventil is NULL and i.calcHLventil is not NULL) ) OR
                ( i.countUserGV <> d.countUserGV OR ( d.countUserGV is NULL and i.countUserGV is not NULL) ) OR
                ( i.countBusinessConsumers <> d.countBusinessConsumers OR ( d.countBusinessConsumers is NULL and i.countBusinessConsumers is not NULL) ) OR
                ( i.area <> d.area OR ( d.area is NULL and i.area is not NULL) ) OR
                ( i.buildingVolume <> d.buildingVolume OR ( d.buildingVolume is NULL and i.buildingVolume is not NULL) ) OR
                ( i.basementVolume <> d.basementVolume OR ( d.basementVolume is NULL and i.basementVolume is not NULL) ) OR
                ( i.builtInVolume <> d.builtInVolume OR ( d.builtInVolume is NULL and i.builtInVolume is not NULL) ) OR
                ( i.heatPointID <> d.heatPointID OR ( d.heatPointID is NULL and i.heatPointID is not NULL) )
            )
BEGIN

UPDATE hp
    set
        raschetnayaNagruzkaCO = IIF( p.raschetnayaNagruzkaCO is NULL, 0 , p.raschetnayaNagruzkaCO ),
        srednyayaNagruzkaGV = IIF( p.srednyayaNagruzkaGV is NULL, 0 , p.srednyayaNagruzkaGV ),
        maxNagruzkaGV = IIF( p.maxNagruzkaGV is NULL, 0 , p.maxNagruzkaGV ),
        raschetnayaNagruzkaSV = IIF( p.raschetnayaNagruzkaSV is NULL, 0 , p.raschetnayaNagruzkaSV ),
        countUserGV = IIF( p.countUserGV is NULL, 0 , p.countUserGV ),
        countBusinessConsumers = IIF( p.countBusinessConsumers is NULL, 0 , p.countBusinessConsumers ),
        area = IIF( p.area is NULL, 0 , p.area ),
        buildingVolume = IIF( p.buildingVolume is NULL, 0 , p.buildingVolume ),
        basementVolume = IIF( p.basementVolume is NULL, 0 , p.basementVolume ),
        builtInVolume = IIF( p.builtInVolume is NULL, 0 , p.builtInVolume )
    from heatPoint hp
    join (
        select rc.raschetnayaNagruzkaCO,
               rc.srednyayaNagruzkaGV,
               rc.maxNagruzkaGV,
               rc.raschetnayaNagruzkaSV,
               rc.countUserGV,
               rc.countBusinessConsumers,
               rc.area,
               rc.buildingVolume,
               rc.basementVolume,
               rc.builtInVolume,
               rc.heatPointID
        from getRealConsumersNagruzkiByHeatPointID() rc
        join inserted i ON i.heatPointID = rc.heatPointID
        )p ON hp.ID = p.heatPointID

UPDATE hp_before
    set
        raschetnayaNagruzkaCO = IIF( p.raschetnayaNagruzkaCO is NULL, 0 , p.raschetnayaNagruzkaCO ),
        srednyayaNagruzkaGV = IIF( p.srednyayaNagruzkaGV is NULL, 0 , p.srednyayaNagruzkaGV ),
        maxNagruzkaGV = IIF( p.maxNagruzkaGV is NULL, 0 , p.maxNagruzkaGV ),
        raschetnayaNagruzkaSV = IIF( p.raschetnayaNagruzkaSV is NULL, 0 , p.raschetnayaNagruzkaSV ),
        countUserGV = IIF( p.countUserGV is NULL, 0 , p.countUserGV ),
        countBusinessConsumers = IIF( p.countBusinessConsumers is NULL, 0 , p.countBusinessConsumers ),
        area = IIF( p.area is NULL, 0 , p.area ),
        buildingVolume = IIF( p.buildingVolume is NULL, 0 , p.buildingVolume ),
        basementVolume = IIF( p.basementVolume is NULL, 0 , p.basementVolume ),
        builtInVolume = IIF( p.builtInVolume is NULL, 0 , p.builtInVolume )
    from heatPoint hp_before
    join deleted d ON d.heatPointID = hp_before.ID
    left join (
        select rc.raschetnayaNagruzkaCO,
                rc.srednyayaNagruzkaGV,
                rc.maxNagruzkaGV,
                rc.raschetnayaNagruzkaSV,
                rc.countUserGV,
                rc.countBusinessConsumers,
                rc.area,
                rc.buildingVolume,
                rc.basementVolume,
                rc.builtInVolume,
                rc.heatPointID
        from getRealConsumersNagruzkiByHeatPointID() rc
        join deleted d ON d.heatPointID = rc.heatPointID
    )p ON d.heatPointID = p.heatPointID

END

GO
ALTER TABLE [dbo].[realConsumers] ENABLE TRIGGER [HeatPointCalc_UPDATE]
GO

