CREATE TRIGGER [dbo].[RealConsumer_INSERT]
ON [dbo].[realConsumers]
AFTER INSERT
AS
    UPDATE nrc
    set heatSourcePTSID = ec.heatSourceID
    from realConsumers nrc
    join inserted i on i.id = nrc.id
    join nodes n on n.id = i.nodeID
    join externalCodes ec on ec.id  = n.externalCodeID

GO
ALTER TABLE [dbo].[realConsumers] ENABLE TRIGGER [RealConsumer_INSERT]
GO
