/****** Object:  UserDefinedFunction [dbo].[avgHeatLosesMonth]    Script Date: 17.01.2023 17:04:49 ******/

GO

SET QUOTED_IDENTIFIER ON
GO

create function [dbo].[avgHeatLosesMonth](@seasonID int) RETURNS  @avgHeatLosesMonth TABLE  (          heatSourceID int,     r int,     m int,     sezon int,     potNP float,     potNO float,     potPodz float,     potAll float,     V1 float,     Vall float ) as BEGIN     INSERT INTO @avgHeatLosesMonth     SELECT         tab1.heatSourceID,         tab1.r,         tab1.m,         tab1.sezon,         sum(potNP) AS potNP,         sum(potNO) AS potNO,         sum(potPodz) AS potPodz,         sum(potP+potO) AS potAll,         sum((         tab1.V*IIF(tab1.sezon=1, 1, 0.5+hls.t_percent/200)+         ISNULL(tab2.Vov, 0)*IIF(tab1.sezon=1, 1, 0)+         ISNULL(tab2.Vgvs, 0)         )*hlm.a/100*tv.dT)/1000 AS V1,         sum(potP+potO+(         tab1.V*IIF(tab1.sezon=1, 1, 0.5+hls.t_percent/200)+         ISNULL(tab2.Vov, 0)*IIF(tab1.sezon=1, 1, 0)+         ISNULL(tab2.Vgvs, 0)         )*hlm.a/100*tv.dT/1000) AS Vall     FROM     (         SELECT             nm.heatSourceID,             nm.r,nm.m,nm.sezon,             sum(qp*lenP*beta*heatTestsCoeffP)/1E6 AS potP,             sum(qo*lenO*beta*heatTestsCoeffO)/1E6 AS potO,             sum(IIF(tubingTypeID IN (1,2), 0, qp*lenP*beta*heatTestsCoeffP))/1E6 AS potNP,             sum(IIF(tubingTypeID IN (1,2), 0, qo*lenO*beta*heatTestsCoeffO))/1E6 AS potNO,             sum(IIF(tubingTypeID IN (1,2), qp*lenP*beta*heatTestsCoeffP+qo*lenO*beta*heatTestsCoeffO, 0))/1E6 AS potPodz,             sum((lenP+lenO)*PI()*POWER(diameterInternal/1000,2)/4) AS V         FROM normMon nm         GROUP BY             nm.r,nm.m,nm.sezon,nm.heatSourceID     ) tab1     LEFT JOIN     (       SELECT           lv.heatSourceID,           Vot+Vvent AS Vov,          Vgvs       FROM losesvolumesview(@seasonID) lv     ) tab2 ON tab2.heatSourceID = tab1.heatSourceID     join heatLosesMain hlm ON hlm.id=@seasonID     JOIN tempView tv ON tv.hID=tab1.heatSourceID AND tv.r=tab1.r AND tv.m <=120     LEFT JOIN heatLosesSource hls ON tab1.heatSourceID=hls.heatSourceID     GROUP BY         tab1.heatSourceID,         tv.tgP,         tv.tgO,         tv.tx,         tv.dT,         tab1.m,         tab1.sezon,         tab1.r     RETURN END;
GO

