ce hls ON tab1.heatSourceID=hls.heatSourceID     GROUP BY         tab1.heatSourceID,         tv.tgP,         tv.tgO,         tv.tx,         tv.dT,         tab1.m,         tab1.sezon,         tab1.r     RETURN END;
