create function [dbo].[losesVolumesViewFragment](@seasonID int) RETURNS  @losesVolumesViewFragment TABLE  (     heatSourceID int,     V1 float,     V2 float,     Vpodv float,     V6 float,     Vsts float,     Vot1 float,     Vvent1 float,     Vgvs1 float,     Vot2 float,     Vvent2 float,     Vgvs2 float,     Vot3 float,     Vvent3 float,     Vgvs3 float,     Vot float,     Vvent float,     Vgvs float,     Vpotr float,     VobM float,     VobR float ) as BEGIN     INSERT INTO @losesVolumesViewFragment SELECT      TR.heatSourceID,     V1,     V2,     Vpodv,       V6,     V1+V2+V6 AS Vsts,     Vot1,     Vvent1,     Vgvs1,     Vot2,     Vvent2,     Vgvs2,     Vot3,     Vvent3,     Vgvs3,     Vot,     Vvent,     Vgvs,     Vot+Vvent+Vgvs AS Vpotr,     IIF(VobM IS NULL, 0, VobM) AS VobM,     IIF(VobR IS NULL, 0, VobR) AS VobR FROM  (   SELECT      heatSourceID,     sum(IIF(objectID = 1 AND typnet <> 20, VV, 0)) AS V1,     sum(IIF(objectID <> 1 AND typnet <> 20, VV, 0)) AS V2,     sum(IIF(typnet = 20, VV, 0)) AS Vpodv,    sum(IIF(typnet<>20 , VV, 0)) AS V6   FROM    (     SELECT        heatSourceID,       diameterExternal,       diameterCondit,       diameterInternal,       objectID,       wallThickness,       typnet,       (lenP+lenO)*diameterInternal*diameterInternal*PI()/4/1000/1000 AS VV     FROM heatPipeSectionIstFragment hps   ) _T1   GROUP BY     heatSourceID ) TR LEFT JOIN  ( SELECT      heatSourceID,     sum(gOt_pr*volWaterHS) AS Vot,     sum(gVent_pr*volWaterVS) AS Vvent,     sum(gGvs_pr*volWaterOpenGvs) AS Vgvs,     sum(gOt_pr1*volWaterHS) AS Vot1,     sum(gVent_pr1*volWaterVS) AS Vvent1,     sum(gGvs_pr1*volWaterOpenGvs) AS Vgvs1,     sum(gOt_pr2*volWaterHS) AS Vot2,     sum(gVent_pr2*volWaterVS) AS Vvent2,     sum(gGvs_pr2*volWaterOpenGvs) AS Vgvs2,     sum(gOt_pr3*volWaterHS) AS Vot3,     sum(gVent_pr3*volWaterVS) AS Vvent3,     sum(gGvs_pr3*volWaterOpenGvs) AS Vgvs3 FROM (   SELECT      ec.heatSourceID,     sum(IIF(buildingTypeID=1,calcHLdep+calcHLindep, 0)) AS gOt_pr1,     sum(IIF(buildingTypeID=1,calcHLventil, 0)) AS gVent_pr1,     sum(IIF(buildingTypeID=1,avgHLGVSopenFlow+avgHLGVSopenRet+avgHLGVScloseParall+avgHLGVScloseMix+avgHLGVScloseConseq+avgHLGVSclosePreON, 0)) AS gGvs_pr1,     sum(IIF(buildingTypeID=2,calcHLdep+calcHLindep, 0)) AS gOt_pr2,     sum(IIF(buildingTypeID=2,calcHLventil, 0)) AS gVent_pr2,     sum(IIF(buildingTypeID=2,avgHLGVSopenFlow+avgHLGVSopenRet+avgHLGVScloseParall+avgHLGVScloseMix+avgHLGVScloseConseq+avgHLGVSclosePreON, 0)) AS gGvs_pr2,     sum(IIF(buildingTypeID=3,calcHLdep+calcHLindep, 0)) AS gOt_pr3,     sum(IIF(buildingTypeID=3,calcHLventil, 0)) AS gVent_pr3,     sum(IIF(buildingTypeID=3,avgHLGVSopenFlow+avgHLGVSopenRet+avgHLGVScloseParall+avgHLGVScloseMix+avgHLGVScloseConseq+avgHLGVSclosePreON, 0)) AS gGvs_pr3,     sum(calcHLdep+calcHLindep) AS gOt_pr,     sum(calcHLventil) AS gVent_pr,     sum(avgHLGVSopenFlow+avgHLGVSopenRet+avgHLGVScloseParall+avgHLGVScloseMix+avgHLGVScloseConseq+avgHLGVSclosePreON) AS gGvs_pr,     IIF(hlm.useTableData=0, rc.volWaterHS, hlm.volWaterHS) AS volWaterHS,     IIF(hlm.useTableData=0, rc.volWaterVS, hlm.volWaterVS) AS volWaterVS,     hlm.volWaterOpenGvs   FROM realConsumers2 rc   JOIN nodes n ON n.id = rc.nodeID   join TEMP_NODE ON n.id=TEMP_NODE.id   left join externalCodes ec on ec.id = n.externalCodeID   join heatLosesMain hlm ON hlm.id=@seasonID   WHERE n.removed=0   GROUP BY     hlm.volWaterHS,     hlm.volWaterVS,     hlm.volWaterOpenGvs,     hlm.useTableData,     rc.volWaterHS,     rc.volWaterVS,     ec.heatSourceID ) _TTT1 GROUP BY     heatSourceID,     volWaterOpenGvs ) PR ON PR.heatSourceID = TR.heatSourceID LEFT JOIN  ( SELECT heatSourceID, SUM(IIF(belongMS=1, V, 0)) AS VObM, SUM(IIF(belongMS<>1, V, 0)) AS VObR    FROM    (     SELECT heatSourceID, belongMS, SUM(POWER(diameterInternal/1000,2)*PI()/4*pipeSectLength) AS V       FROM heatPipeSectionsHarness       GROUP BY       heatSourceID,belongMS   ) _TT1   GROUP BY heatSourceID ) OBV ON OBV.heatSourceID=TR.heatSourceID     RETURN END;
