calcHLindep, 0)) AS gOt_pr1,     sum(IIF(buildingTypeID=1,calcHLventil, 0)) AS gVent_pr1,     sum(IIF(buildingTypeID=1,avgHLGVSopenFlow+avgHLGVSopenRet+avgHLGVScloseParall+avgHLGVScloseMix+avgHLGVScloseConseq+avgHLGVSclosePreON, 0)) AS gGvs_pr1,     sum(IIF(buildingTypeID=2,calcHLdep+calcHLindep, 0)) AS gOt_pr2,     sum(IIF(buildingTypeID=2,calcHLventil, 0)) AS gVent_pr2,     sum(IIF(buildingTypeID=2,avgHLGVSopenFlow+avgHLGVSopenRet+avgHLGVScloseParall+avgHLGVScloseMix+avgHLGVScloseConseq+avgHLGVSclosePreON, 0)) AS gGvs_pr2,     sum(IIF(buildingTypeID=3,calcHLdep+calcHLindep, 0)) AS gOt_pr3,     sum(IIF(buildingTypeID=3,calcHLventil, 0)) AS gVent_pr3,     sum(IIF(buildingTypeID=3,avgHLGVSopenFlow+avgHLGVSopenRet+avgHLGVScloseParall+avgHLGVScloseMix+avgHLGVScloseConseq+avgHLGVSclosePreON, 0)) AS gGvs_pr3,     sum(calcHLdep+calcHLindep) AS gOt_pr,     sum(calcHLventil) AS gVent_pr,     sum(avgHLGVSopenFlow+avgHLGVSopenRet+avgHLGVScloseParall+avgHLGVScloseMix+avgHLGVScloseConseq+avgHLGVSclosePreON) AS gGvs_pr,     IIF(hlm.useTableData=0, rc.volWaterHS, hlm.volWaterHS) AS volWaterHS,     IIF(hlm.useTableData=0, rc.volWaterVS, hlm.volWaterVS) AS volWaterVS,     hlm.volWaterOpenGvs   FROM realConsumers2 rc   JOIN nodes n ON n.id = rc.nodeID   join TEMP_NODE ON n.id=TEMP_NODE.id   left join externalCodes ec on ec.id = n.externalCodeID   join heatLosesMainFact hlm ON hlm.id=@seasonID   WHERE n.removed=0   GROUP BY     hlm.volWaterHS,     hlm.volWaterVS,     hlm.volWaterOpenGvs,     hlm.useTableData,     rc.volWaterHS,     rc.volWaterVS,     ec.heatSourceID ) _TTT1 GROUP BY     heatSourceID,     volWaterOpenGvs ) PR ON PR.heatSourceID = TR.heatSourceID LEFT JOIN  ( SELECT heatSourceID, SUM(IIF(belongMS=1, V, 0)) AS VObM, SUM(IIF(belongMS<>1, V, 0)) AS VObR    FROM    (     SELECT heatSourceID, belongMS, SUM(POWER(diameterInternal/1000,2)*PI()/4*pipeSectLength) AS V       FROM heatPipeSectionsHarness       GROUP BY       heatSourceID,belongMS   ) _TT1   GROUP BY heatSourceID ) OBV ON OBV.heatSourceID=TR.heatSourceID     RETURN END;
