create function [dbo].[psvView](@seasonID int) RETURNS  @psvView TABLE  ( heatSourceID int,  r int, m int, sezon int, fillingG float,  fillingQ float,  avgGpressingG float, avgGpressingQ float, avgGflushingG float, avgGflushingQ float, avgGsarzG float, avgGsarzQ float, normG float, normQ float ) as BEGIN     INSERT INTO @psvView SELECT lsm.heatSourceID, lsm.r,lsm.m,lsm.sezon,   IIF((((V1+VobM)*1.5*bf.magistralShare/100 +(V2+Vpodv+Vobr)*1.2*bf.distSiteShare/100 +(Vot+Vvent+Vgvs)*1.2*bf.heatingSystemShare/100)) IS NULL,0, (((V1+VobM)*1.5*bf.magistralShare/100 +(V2+Vpodv+Vobr)*1.2*bf.distSiteShare/100 +(Vot+Vvent+Vgvs)*1.2*bf.heatingSystemShare/100))) AS fillingG,    (IIF((((V1+VobM)*1.5*bf.magistralShare/100 +(V2+Vpodv+Vobr)*1.2*bf.distSiteShare/100 +(Vot+Vvent+Vgvs)*1.2*bf.heatingSystemShare/100)) IS NULL,0, (((V1+VobM)*1.5*bf.magistralShare/100 +(V2+Vpodv+Vobr)*1.2*bf.distSiteShare/100 +(Vot+Vvent+Vgvs)*1.2*bf.heatingSystemShare/100))))*(IIF(bf.netTemperature IS NULL,0,bf.netTemperature)-lsm.tx)/1000 AS fillingQ,    IIF(lsm.m=hls.pressingMonth1 AND lsm.sezon=2, (V1+VobM+V2+Vpodv+VobR)*hls.spring_pressing/100,    IIF(lsm.m=hls.pressingMonth2 AND lsm.sezon=2, (V1+VobM+V2+Vpodv+VobR)*hls.autumn_pressing/100, 0))    AS avgGpressingG,   IIF(lsm.m=hls.pressingMonth1 AND lsm.sezon=2, (V1+VobM+V2+Vpodv+VobR)*hls.spring_pressing/100*(hls.netTempPressing1-hls.coldTempPressing1)/1000,    IIF(lsm.m=hls.pressingMonth2 AND lsm.sezon=2, (V1+VobM+V2+Vpodv+VobR)*hls.autumn_pressing/100*(hls.netTempPressing2-hls.coldTempPressing2)/1000, 0))    AS avgGpressingQ,   IIF(lsm.m=hls.pressingMonth1 AND lsm.sezon=2, (V1+VobM+V2+Vpodv+VobR)*hls.flushing*(hls.flushing_flow+hls.flushing_ret)/2, 0) AS avgGflushingG,   IIF(lsm.m=hls.pressingMonth1 AND lsm.sezon=2, (V1+VobM+V2+Vpodv+VobR)*hls.flushing*(hls.flushing_flow+hls.flushing_ret)/2, 0)*(hls.flushing_temp1-hls.flushinghs_temp2) AS avgGflushingQ,   lsm.workCountFlow*lsm.netWaterExpFlow*(lsm.regCountFlow+lsm.regCountNodeFlow)*24+lsm.workCountRet*lsm.netWaterExpRet*(lsm.regCountRet+lsm.regCountNodeRet)*24 AS avgGsarzG,   (lsm.workCountFlow*lsm.netWaterExpFlow*(lsm.regCountFlow+lsm.regCountNodeFlow)*24+lsm.workCountRet*lsm.netWaterExpRet*(lsm.regCountRet+lsm.regCountNodeRet)*24)*(tv.tgP-tv.tx)/1000 AS avgGsarzQ,   ((V1+VobM+V2+Vpodv+VobR)*IIF(lsm.sezon=1, 1, 0.5+hls.t_percent/200)+     ((lv.Vot+lv.Vvent)*IIF(lsm.sezon=1, 1, 0)+lv.Vgvs)   )*lm.a/100*lsm.workCount*24 AS normG,   (((V1+VobM+V2+Vpodv+VobR)*IIF(lsm.sezon=1, 1, 0.5+hls.t_percent/200)+     ((lv.Vot+lv.Vvent)*IIF(lsm.sezon=1, 1, 0)+lv.Vgvs)   )*lm.a/100*lsm.workCount*24)*tv.dt/1000 AS normQ FROM heatLosesSourceMonths lsm LEFT JOIN heatLosesSource hls ON lsm.heatSourceID=hls.heatSourceID LEFT JOIN losesvolumesview(@seasonID) lv ON lv.heatSourceID=lsm.heatSourceID LEFT JOIN losesByFilling bf ON BF.heatSourceID = lsm.heatSourceID AND bf.monthID=lsm.m AND lsm.sezon=2 LEFT JOIN heatLosesMain lm ON lm.id=@seasonID LEFT JOIN tempView tv ON tv.hID=lsm.heatSourceID AND tv.r=lsm.r AND tv.m=lsm.m     RETURN END;
GO

