m.regCountNodeFlow)*24   +lsm.workCountRet*lsm.netWaterExpRet*(lsm.regCountRet+lsm.regCountNodeRet)*24   AS avgGsarzG,   (lsm.workCountFlow*lsm.netWaterExpFlow*(lsm.regCountFlow+lsm.regCountNodeFlow)*24   +lsm.workCountRet*lsm.netWaterExpRet*(lsm.regCountRet+lsm.regCountNodeRet)*24  )*(tv.tgP-tv.tx)/1000 AS avgGsarzQ,   ((V1+VobM+V2+Vpodv+VobR)*IIF(lsm.sezon=1, 1, 0.5+hls.t_percent/200)+     ((lv.Vot+lv.Vvent)*IIF(lsm.sezon=1, 1, 0)+lv.Vgvs)   )*lm.a/100*lsm.workCount*24 AS normG,   (((V1+VobM+V2+Vpodv+VobR)*IIF(lsm.sezon=1, 1, 0.5+hls.t_percent/200)+     ((lv.Vot+lv.Vvent)*IIF(lsm.sezon=1, 1, 0)+lv.Vgvs)   )*lm.a/100*lsm.workCount*24)*tv.dt/1000 AS normQ FROM heatLosesSourceMonthsFact lsm LEFT JOIN heatLosesSourceFact hls ON lsm.heatSourceID=hls.heatSourceID LEFT JOIN losesVolumesViewFragmentFact(@seasonID) lv ON lv.heatSourceID=lsm.heatSourceID LEFT JOIN losesByFillingFact bf ON BF.heatSourceID = lsm.heatSourceID AND bf.monthID=lsm.m AND lsm.sezon=2 LEFT JOIN heatLosesMainFact lm ON lm.id=@seasonID LEFT JOIN tempViewFact tv ON tv.hID=lsm.heatSourceID AND tv.r=lsm.r AND tv.m=lsm.m     RETURN END;
