create function [dbo].[tankbatteryViewFragmentFact](@seasonID int) RETURNS  @tankbatteryViewFragmentFact TABLE  (   heatSourceID int,   r int,   m int,   tn float,   tgO float,   qTB float,   workCount int ) as BEGIN     INSERT INTO @tankbatteryViewFragmentFact SELECT   TAB2.heatSourceID,   TAB2.r,   TAB2.m,   TAB2.tn,   TAB2.tgO,   SUM(TAB2.q) AS qTB,   TAB2.workCount FROM    heatLosesMainFact h1 JOIN  ( SELECT    hlm.id,   iif(ec.objectID  <> 2, ec.heatSourceID, ecm.heatSourceID) AS heatSourceID,   ec.name, n.externalNodeName, tv.r, tv.m, tv.sezon, tv.tn, tv.tgO, b.designCapacity, b.quantity, b.height, b.diameter, PI()*b.diameter/1000*(b.height+b.diameter/2)/1000*2 AS F, PI()*b.diameter/1000*(b.height+b.diameter/2)/1000*2*hlm.tankbattery_q/1000000*(tv.tgO-tv.tx)/(tvg.tgO-tvg.tx) AS q, (tv.tgO-tv.tx)/(tvg.tgO-tvg.tx) AS TT, tv.workCount FROM tankBatteries b JOIN nodes n ON b.nodeID = n.id join TEMP_NODE ON n.id=TEMP_NODE.id JOIN externalCodes ec ON n.externalCodeID = ec.id left join externalCodes ecm on ec.belongMagistral = ecm.id AND ec.objectID=2 LEFT JOIN tempViewFact tv ON tv.hID=iif(ec.objectID  <> 2, ec.heatSourceID, ecm.heatSourceID) LEFT JOIN tempViewFact tvg ON tv.hID=iif(ec.objectID  <> 2, ec.heatSourceID, ecm.heatSourceID) AND tvg.m=15 LEFT JOIN heatLosesMainFact hlm ON hlm.id=@seasonID ) TAB2 ON TAB2.id=h1.id LEFT JOIN heatLosesSourceMonthsFact lsm ON lsm.heatSourceID=TAB2.heatSourceID AND lsm.r=TAB2.r AND TAB2.m=lsm.m GROUP BY   TAB2.heatSourceID,   TAB2.TT,   TAB2.workCount,   TAB2.r,   TAB2.m,   TAB2.sezon,   TAB2.tn,   TAB2.tgO     RETURN END;
GO

