create function [dbo].[get_qq](   @tubingTypeID int,    @y INT,     @kolwork INT,   @po INT,    @tgP FLOAT,      @tgO FLOAT,      @tgr FLOAT,     @tpodv FLOAT,    @tn FLOAT,      @tnSt FLOAT,    @tgrSt FLOAT,     @t2 FLOAT,   @t1_1 FLOAT, @t1_2 FLOAT, @t1_3 FLOAT, @t1_4 FLOAT,   @qp_1 FLOAT, @qo_1 FLOAT, @qp_2 FLOAT, @qo_2 FLOAT, @qp_3 FLOAT, @qo_3 FLOAT, @qp_4 FLOAT, @qo_4 FLOAT,    @qp_1_5000 FLOAT, @qo_1_5000 FLOAT, @qp_2_5000 FLOAT, @qo_2_5000 FLOAT, @qp_3_5000 FLOAT, @qo_3_5000 FLOAT, @qp_4_5000 FLOAT, @qo_4_5000 FLOAT  ) returns FLOAT BEGIN   DECLARE @q FLOAT;   DECLARE @qP FLOAT;   DECLARE @qO FLOAT;   DECLARE @t FLOAT;   IF @kolwork = 1 BEGIN     SET @qp_1 = @qp_1_5000;     SET @qp_2 = @qp_2_5000;     SET @qp_3 = @qp_3_5000;     SET @qp_4 = @qp_4_5000;     SET @qo_1 = @qo_1_5000;     SET @qo_2 = @qo_2_5000;     SET @qo_3 = @qo_3_5000;     SET @qo_4 = @qo_4_5000;   END    IF @tubingTypeID = 4 OR @tubingTypeID = 3 BEGIN       IF @po = 2 BEGIN              SET @t = @tgO;     END     ELSE BEGIN       SET @t = @tgP;     END    END   ELSE BEGIN      SET @t = (@tgP+@tgO)/2;   END    IF @y = 1 BEGIN     IF @tubingTypeID = 4 BEGIN         SET @t = @t-@tn;     END     ELSE IF @tubingTypeID = 3 BEGIN         SET @t = @t-@tpodv;     END     ELSE BEGIN       SET @t = @t-@tgr;                 END    END    IF @y <> 1 BEGIN       SET @tnSt = 0;     SET @tgrSt = 0;   END    IF @tubingTypeID = 4 OR @tubingTypeID = 3 BEGIN       SET @qP = dbo.interpolate_q_3(@t, @t1_1-@tnSt, @t1_2-@tnSt, @t1_3-@tnSt, @t1_4-@tnSt, @qp_1, @qp_2, @qp_3, @qp_4);     return @qP;   END    IF @po = 1 BEGIN     SET @q = dbo.interpolate_q_3(@t, (@t1_1+@t2)/2-@tgrSt, (@t1_2+@t2)/2-@tgrSt, (@t1_3+@t2)/2-@tgrSt, (@t1_4+@t2)/2-@tgrSt, @qp_1, @qp_2, @qp_3, @qp_4);   END   ELSE BEGIN      SET @q = dbo.interpolate_q_3(@t, (@t1_1+@t2)/2-@tgrSt, (@t1_2+@t2)/2-@tgrSt, (@t1_3+@t2)/2-@tgrSt, (@t1_4+@t2)/2-@tgrSt, @qo_1, @qo_2, @qo_3, @qo_4);   END    return @q; END; ;
GO

