create function [dbo].[getCoeff](    @po int,     @coeffDefault int,    @heatTestsCoeff FLOAT,    @pipeRemontTypeID int,    @tubingTypeID int,    @y int,    @typnet int,  @coeffMsFlowNorms1 FLOAT, @coeffMsRetNorms1 FLOAT, @coeffMsUndergroundNorms1 FLOAT, @coeffRsFlowNorms1 FLOAT, @coeffRsRetNorms1 FLOAT, @coeffRsUndergroundNorms1 FLOAT, @coeffBasementFlowNorms1 FLOAT, @coeffBasementRetNorms1 FLOAT, @coeffBasementUndergroundNorms1 FLOAT, @coeffHarnessFlowNorms1 FLOAT, @coeffHarnessRetNorms1 FLOAT, @coeffHarnessUndergroundNorms1 FLOAT, @coeffMsFlowNorms3 FLOAT, @coeffMsRetNorms3 FLOAT, @coeffMsUndergroundNorms3 FLOAT, @coeffRsFlowNorms3 FLOAT, @coeffRsRetNorms3 FLOAT, @coeffRsUndergroundNorms3 FLOAT, @coeffBasementFlowNorms3 FLOAT, @coeffBasementRetNorms3 FLOAT, @coeffBasementUndergroundNorms3 FLOAT, @coeffHarnessFlowNorms3 FLOAT, @coeffHarnessRetNorms3 FLOAT, @coeffHarnessUndergroundNorms3 FLOAT, @coeffMsFlowNorms1_r FLOAT, @coeffMsRetNorms1_r FLOAT, @coeffMsUndergroundNorms1_r FLOAT, @coeffRsFlowNorms1_r FLOAT, @coeffRsRetNorms1_r FLOAT, @coeffRsUndergroundNorms1_r FLOAT, @coeffBasementFlowNorms1_r FLOAT, @coeffBasementRetNorms1_r FLOAT, @coeffBasementUndergroundNorms1_r FLOAT, @coeffHarnessFlowNorms1_r FLOAT, @coeffHarnessRetNorms1_r FLOAT, @coeffHarnessUndergroundNorms1_r FLOAT, @coeffMsFlowNorms3_r FLOAT, @coeffMsRetNorms3_r FLOAT, @coeffMsUndergroundNorms3_r FLOAT, @coeffRsFlowNorms3_r FLOAT, @coeffRsRetNorms3_r FLOAT, @coeffRsUndergroundNorms3_r FLOAT, @coeffBasementFlowNorms3_r FLOAT, @coeffBasementRetNorms3_r FLOAT, @coeffBasementUndergroundNorms3_r FLOAT, @coeffHarnessFlowNorms3_r FLOAT, @coeffHarnessRetNorms3_r FLOAT, @coeffHarnessUndergroundNorms3_r FLOAT ) RETURNS FLOAT BEGIN   DECLARE @ret FLOAT;   IF @coeffDefault = 0 BEGIN     RETURN @heatTestsCoeff;   END    IF @pipeRemontTypeID = 1 BEGIN     RETURN 1;   END    IF @pipeRemontTypeID = 2 BEGIN     SET @coeffMsFlowNorms1 = @coeffMsFlowNorms1_r;     SET @coeffMsRetNorms1 = @coeffMsRetNorms1_r;     SET @coeffMsUndergroundNorms1 = @coeffMsUndergroundNorms1_r;     SET @coeffRsFlowNorms1 = @coeffRsFlowNorms1_r;     SET @coeffRsRetNorms1 = @coeffRsRetNorms1_r;     SET @coeffRsUndergroundNorms1 = @coeffRsUndergroundNorms1_r;     SET @coeffBasementFlowNorms1 = @coeffBasementFlowNorms1_r;     SET @coeffBasementRetNorms1 = @coeffBasementRetNorms1_r;     SET @coeffBasementUndergroundNorms1 = @coeffBasementUndergroundNorms1_r;     SET @coeffHarnessFlowNorms1 = @coeffHarnessFlowNorms1_r;     SET @coeffHarnessRetNorms1 = @coeffHarnessRetNorms1_r;     SET @coeffHarnessUndergroundNorms1 = @coeffHarnessUndergroundNorms1_r;     SET @coeffMsFlowNorms3 = @coeffMsFlowNorms3_r;     SET @coeffMsRetNorms3 = @coeffMsRetNorms3_r;     SET @coeffMsUndergroundNorms3 = @coeffMsUndergroundNorms3_r;     SET @coeffRsFlowNorms3 = @coeffRsFlowNorms3_r;     SET @coeffRsRetNorms3 = @coeffRsRetNorms3_r;     SET @coeffRsUndergroundNorms3 = @coeffRsUndergroundNorms3_r;     SET @coeffBasementFlowNorms3 = @coeffBasementFlowNorms3_r;     SET @coeffBasementRetNorms3 = @coeffBasementRetNorms3_r;     SET @coeffBasementUndergroundNorms3 = @coeffBasementUndergroundNorms3_r;     SET @coeffHarnessFlowNorms3 = @coeffHarnessFlowNorms3_r;     SET @coeffHarnessRetNorms3 = @coeffHarnessRetNorms3_r;     SET @coeffHarnessUndergroundNorms3 = @coeffHarnessUndergroundNorms3_r;   END    IF @y <> 1 BEGIN     SET @coeffMsFlowNorms1 = @coeffMsFlowNorms3;     SET @coeffMsRetNorms1 = @coeffMsRetNorms3;     SET @coeffMsUndergroundNorms1 = @coeffMsUndergroundNorms3;     SET @coeffRsFlowNorms1 = @coeffRsFlowNorms3;     SET @coeffRsRetNorms1 = @coeffRsRetNorms3;     SET @coeffRsUndergroundNorms1 = @coeffRsUndergroundNorms3;     SET @coeffBasementFlowNorms1 = @coeffBasementFlowNorms3;     SET @coeffBasementRetNorms1 = @coeffBasementRetNorms3;     SET @coeffBasementUndergroundNorms1 = @coeffBasementUndergroundNorms3;     SET @coeffHarnessFlowNorms1 = @coeffHarnessFlowNorms3;     SET @coeffHarnessRetNorms1 = @coeffHarnessRetNorms3;     SET @coeffHarnessUndergroundNorms1 = @coeffHarnessUndergroundNorms3;   END    IF @typnet = 2 BEGIN     SET @coeffMsFlowNorms1 = @coeffRsFlowNorms1;     SET @coeffMsRetNorms1 = @coeffRsRetNorms1;     SET @coeffMsUndergroundNorms1 = @coeffRsUndergroundNorms1;   END   ELSE IF @typnet = 20 BEGIN     SET @coeffMsFlowNorms1 = @coeffBasementFlowNorms1;     SET @coeffMsRetNorms1 = @coeffBasementRetNorms1;     SET @coeffMsUndergroundNorms1 = @coeffBasementUndergroundNorms1;   END      IF @tubingTypeID IN (1,2) BEGIN     return @coeffMsUndergroundNorms1;   END    IF @po = 1 BEGIN     return @coeffMsFlowNorms1;   END    return @coeffMsRetNorms1; END; ;
GO

