/****** Object:  UserDefinedFunction [dbo].[interpolate_q_3]    Script Date: 17.01.2023 17:12:28 ******/

GO

SET QUOTED_IDENTIFIER ON
GO

create function [dbo].[interpolate_q_3](   @t FLOAT,   @t1 FLOAT, @t2 FLOAT, @t3 FLOAT, @t4 FLOAT,   @q1 FLOAT, @q2 FLOAT, @q3 FLOAT, @q4 FLOAT ) RETURNS FLOAT BEGIN   IF @t < @t2 BEGIN RETURN @q1+(@q2-@q1)*(@t-@t1)/(@t2-@t1); END    IF @t < @t3 AND @t3 <> @t2 BEGIN RETURN @q2+(@q3-@q2)*(@t-@t2)/(@t3-@t2); END    IF @t < @t4 AND @t4 <> @t3 BEGIN RETURN @q3+(@q4-@q3)*(@t-@t3)/(@t4-@t3); END    IF @t2 = @t3 BEGIN     RETURN @q1+(@q2-@q1)*(@t-@t1)/(@t2-@t1);     END    IF @t3 = @t4 BEGIN     RETURN @q2+(@q3-@q2)*(@t-@t2)/(@t3-@t2);   END    RETURN @q3+(@q4-@q3)*(@t-@t3)/(@t4-@t3); END; ;
GO

/****** Object:  UserDefinedFunction [dbo].[shift_coord]    Script Date: 17.01.2023 17:13:10 ******/

GO

SET QUOTED_IDENTIFIER ON
GO

create   function [dbo].[shift_coord](
  @list varchar(8000),
  @dx decimal,
  @dy decimal



) returns varchar(8000)

BEGIN

DECLARE @pos INT;
DECLARE @len INT;
DECLARE @len2 INT;

DECLARE @value varchar(8000);
DECLARE @value2 decimal(20,2);
DECLARE @limit varchar(10);
DECLARE @limit2 varchar(10);
DECLARE @zpt varchar(10);

DECLARE @out varchar(8000);
DECLARE @even INT;
DECLARE @x decimal;
DECLARE @y decimal;
DECLARE @xy decimal;



set @limit = ' '
set @limit2 = ' '
set @zpt = ','

set @pos = 0
set @len = 0

set @out = ''
set @even = 0

IF @list = '' OR @list IS NULL BEGIN
  RETURN '';
END


set @list = @list + ' '



WHILE CHARINDEX(@limit, @list, @pos+1)>0
BEGIN
    set @len = CHARINDEX(@limit, @list, @pos+1) - @pos

    set @value = SUBSTRING(@list, @pos, @len)


    set @xy = try_convert(decimal(20,2), @value)

    set @pos = CHARINDEX(@limit, @list, @pos+@len) +1

  IF @even = 0 BEGIN
    set @even = 1
    set @limit2 = ','
    set @xy = @xy - @dx
  END
    ELSE BEGIN
    set @even = 0
    set @limit2 = ' '
    set @xy = @xy - @dy
  END

  IF @out = '' BEGIN
    set @out = @xy
  END
  ELSE BEGIN
    set @out = CONCAT(@out, @limit2, @xy)
  END



END

  set @out = CONCAT(@out, ',')

  return @out
END
GO

