create view [dbo].[tempView] as SELECT   hID,   r,   m,   sezon,    tn,   tpod,   tgr,   tgP,   tgO,   tx,   ((tgP+tgO)/2-tx) AS dT,   ((tgP+tgO)/2-tgr) AS dTgr,   ((tgP+tgO)/2-tpod) AS dTpod,   workCount FROM ( SELECT   heatSourceID AS hID,   iif(sezon=1, 15, 16) AS r,   iif(sezon=1, 13, 14) AS m,   sezon,    sum(tn*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tn,   sum(tpod*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tpod,   sum(tgr*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tgr,   sum(tgP*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tgP,   sum(tgO*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tgO,   sum(tx*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tx,   sum(workCount) AS workCount FROM (   SELECT      heatSourceID,     r,      m,      sezon,      tn,      tpod,      tgr,     tgP,      tgO,      tx,      workCount    FROM heatLosesSourceMonths ) _T1 GROUP BY   heatSourceID,   sezon UNION   SELECT      heatSourceID,     r,      m,      sezon,      tn,      tpod,      tgr,     tgP,      tgO,      tx,      workCount    FROM heatLosesSourceMonths hls UNION SELECT   heatSourceID,   17 AS r,   15 AS m,   3,    sum(tn*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tn,   sum(tpod*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tpod,   sum(tgr*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tgr,   sum(tgP*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tgP,   sum(tgO*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tgO,   sum(tx*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tx,   sum(workCount) AS workCount FROM (   SELECT      heatSourceID,     r,      m,      sezon,      tn,      tpod,      tgr,     tgP,      tgO,      tx,      workCount    FROM heatLosesSourceMonths hls ) _T2 GROUP BY   heatSourceID ) _T3 ;
GO

