undNorms3, coeffBasementFlowNorms3,coeffBasementRetNorms3,coeffBasementUndergroundNorms3, coeffHarnessFlowNorms3,coeffHarnessRetNorms3,coeffHarnessUndergroundNorms3, coeffMsFlowNorms1_r,coeffMsRetNorms1_r,coeffMsUndergroundNorms1_r, coeffRsFlowNorms1_r,coeffRsRetNorms1_r,coeffRsUndergroundNorms1_r, coeffBasementFlowNorms1_r,coeffBasementRetNorms1_r,coeffBasementUndergroundNorms1_r, coeffHarnessFlowNorms1_r,coeffHarnessRetNorms1_r,coeffHarnessUndergroundNorms1_r, coeffMsFlowNorms3_r,coeffMsRetNorms3_r,coeffMsUndergroundNorms3_r, coeffRsFlowNorms3_r,coeffRsRetNorms3_r,coeffRsUndergroundNorms3_r, coeffBasementFlowNorms3_r,coeffBasementRetNorms3_r,coeffBasementUndergroundNorms3_r, coeffHarnessFlowNorms3_r,coeffHarnessRetNorms3_r,coeffHarnessUndergroundNorms3_r   ) AS heatTestsCoeffO   ,     signNumWork,     lenP,     lenO FROM (  SELECT     l.id,    ec2.objectID,    IIF(ec2.objectID  <> 2, ec2.heatSourceID, ecm.heatSourceID) AS heatSourceID,    IIF(YEAR(lastTransDate) < 1990, 1, IIF(YEAR(lastTransDate) < 1998, 2, IIF(YEAR(lastTransDate) <= 2003, 3, 4))) AS y_norm,    diameterExternal,    diameterCondit,    diameterInternal,    wallThickness,    tubingTypeID,    l.organizationID AS orgID,    coeffDefault,    heatTestsCoeff,    pipeRemontTypeID,    coeffMsFlowNorms1,coeffMsRetNorms1,coeffMsUndergroundNorms1,coeffRsFlowNorms1,coeffRsRetNorms1,coeffRsUndergroundNorms1, coeffBasementFlowNorms1,coeffBasementRetNorms1,coeffBasementUndergroundNorms1, coeffHarnessFlowNorms1,coeffHarnessRetNorms1,coeffHarnessUndergroundNorms1, coeffMsFlowNorms3,coeffMsRetNorms3,coeffMsUndergroundNorms3, coeffRsFlowNorms3,coeffRsRetNorms3,coeffRsUndergroundNorms3, coeffBasementFlowNorms3,coeffBasementRetNorms3,coeffBasementUndergroundNorms3, coeffHarnessFlowNorms3,coeffHarnessRetNorms3,coeffHarnessUndergroundNorms3, coeffMsFlowNorms1_r,coeffMsRetNorms1_r,coeffMsUndergroundNorms1_r, coeffRsFlowNorms1_r,coeffRsRetNorms1_r,coeffRsUndergroundNorms1_r, coeffBasementFlowNorms1_r,coeffBasementRetNorms1_r,coeffBasementUndergroundNorms1_r, coeffHarnessFlowNorms1_r,coeffHarnessRetNorms1_r,coeffHarnessUndergroundNorms1_r, coeffMsFlowNorms3_r,coeffMsRetNorms3_r,coeffMsUndergroundNorms3_r, coeffRsFlowNorms3_r,coeffRsRetNorms3_r,coeffRsUndergroundNorms3_r, coeffBasementFlowNorms3_r,coeffBasementRetNorms3_r,coeffBasementUndergroundNorms3_r, coeffHarnessFlowNorms3_r,coeffHarnessRetNorms3_r,coeffHarnessUndergroundNorms3_r,    IIF(tubingTypeID = 3, 20,      IIF(tubingTypeID = 5, 30,        case ec2.objectID      when 1 then 1          when 2 then 2          when 10 then 3         when 11 then 4         when 12 then 5         when 3 then 6          when 4 then 7          when 5 then 8          when 6 then 9          when 7 then 10          when 8 then 11          when 9 then 12          else 40      end     ))  AS typnet,     IIF(YEAR(lastTransDate) < 1990, 1, signNumWork) AS signNumWork,     IIF(externalSignLineID IN (1,2,4), pipeSectLength, 0) AS lenP,     IIF(externalSignLineID IN (1,3,5), pipeSectLength, 0) AS lenO  FROM heatPipeSections hps  left join linesobj l on l.id = hps.lineID  join TEMP_LINE ON l.id=TEMP_LINE.id  left join nodes n2 on n2.id = l.nodeID2  left join externalCodes ec2 on ec2.id = n2.externalCodeID   left join externalCodes ecm on ec2.belongMagistral = ecm.id AND ec2.objectID=2  left join heatLosesSourceFact hls on hls.heatSourceID=IIF(ec2.objectID  <> 2, ec2.heatSourceID, ecm.heatSourceID)  WHERE n2.internalNodeID is NULL AND l.removed=0 ) _TTT2 ;
GO


