create view [dbo].[UT_KTP_OUT_view] AS SELECT DISTINCT diameterCondit AS diameterCondit_KTP, tubingTypeID AS tubingTypeID_KTP,  CASE WHEN  diameterCondit >= diametr THEN beta_mag ELSE  beta_rasp END AS beta FROM heatPipeSections LEFT JOIN sprav.dbo.[30_koeffitsienty_mestnyh_teplovyh_poter] s10 ON s10.id=1 AND tubingTypeID=2 OR s10.id=2 AND (tubingTypeID=1 OR tubingTypeID=3) OR s10.id=3 AND tubingTypeID=4 ORDER BY    diameterCondit, tubingTypeID OFFSET 0 ROWS ;
GO


