5000,             qo_1gt5000, qo_2gt5000, qo_3gt5000, qo_4gt5000         FROM sprav.dbo.[39_Normy_teplovyh_poter] s39     ) s39     ON (diameterExternal=s39.d OR diameterCondit=s39.dy) AND y_norm=s39.yy AND (tubingTypeID = tubingTypeID_39 OR (tubingTypeID IN (3,4,5) AND tubingTypeID_39=4))     JOIN tempViewFact ON tempViewFact.hID=L1.heatSourceID     LEFT JOIN ut_ktp_out_view ON ut_ktp_out_view.diameterCondit_KTP=diameterCondit AND ut_ktp_out_view.tubingTypeID_KTP = tubingTypeID ;
