create view [dbo].[realConsumers2] AS SELECT [id]       ,[nodeID]       ,[consumerStateID]       ,[calcHLdep]       ,[calcHLindep]       ,[calcInternHD]       ,[calcHLventil]       ,[avgHLcond]       ,[avgHLcloseSys]       ,[avgHLopenSysFlow]       ,[avgHLopenSysRet]       ,[avgHLGVSopenFlow]       ,[avgHLGVSopenRet]       ,[avgHLGVScloseParall]       ,[avgHLGVScloseMix]       ,[avgHLGVScloseConseq]       ,[avgHLGVSclosePreON]       ,[volWaterHS]       ,[volWaterVS]       ,[buildingTypeID] ,[WEmeteringDeviceID] ,[calcSignResWDORetID] ,[closeSysCalcSignID] ,[calcSignOpenSysFlowID] ,[calcSignSetLoadCloseSys] ,[calcSignSetLoadOpenSysFlow] ,[calcSignSetLoadOpenSysRet] ,[varCoeffID] ,[gvsLoadGraphID] ,[calcTemperatureID] ,[specExpendID] ,[hydroModeSignID] ,[PDvalveInstallLocID] ,[responsibleID] ,[automDegID] ,[calcFerDiameterSignID] ,[temperChartSignID] ,[throtStageSignID] ,[stopValveTypeID] ,[circHLosOpen]   FROM [realConsumers] UNION SELECT gc.[id]       ,[nodeID]       ,[consumerStateID]       ,[calcHLdep]+[calcHLparall]+[calcHLconseq]+[calcHLmix]+[calcHLpreON] as calcHLdep       ,[calcHLindep]       ,[calcInternHDdep]+[calcInternHDindep] AS [calcInternHD]       ,[calcHLventil]       ,IIF(calcHLcond IS NULL, 0, calcHLcond) AS calcHLcond       ,[calcHLcloseSys]       ,[calcHLopenSysFlow]       ,[calcHLopenSysRet]       ,[avgHLGVSopenSysFlow]       ,[avgHLGVSopenSysRet]       ,[calcHLGVSparall]       ,[calcHLGVSmix]       ,[calcHLGVSconseq]       ,[calcHLGVSpreON]       ,[volWaterHS]       ,[volWaterVS]       , 1 AS buildingTypeID ,[WEmeteringDeviceID] ,[calcSignResWDORetID] ,[closeSysCalcSignID] ,[calcSignOpenSysFlowID] ,[calcSignSetLoadCloseSys] ,[calcSignSetLoadOpenSysFlow] ,[calcSignSetLoadOpenSysRet] ,[varCoeffID] ,[gvsLoadGraphID] ,[calcTemperatureID] ,[specExpendID] ,[hydroModeSignID] ,[PDvalveInstallLocID] ,NULL AS [responsibleID] ,1 AS [automDegID] ,1 AS [calcFerDiameterSignID] ,1 AS [temperChartSignID] ,1 AS [throtStageSignID] ,1 AS [stopValveTypeID] ,0 AS [circHLosOpen]   FROM [generalizedConsumers] gc   JOIN nodes n ON n.id=gc.nodeID   join externalCodes ec ON ec.id=n.externalCodeID AND ec.objectID <> 1 AND ec.objectID <> 9 ;
GO

