create view [dbo].[realConsumerIstFact] as   SELECT      n.id,     n.externalCodeID,     n.externalNodeName,     iif(ec.objectID  <> 2, ec.heatSourceID, ecm.heatSourceID) AS heatSourceID,     calcHLdep+calcHLindep AS gOt_pr,     calcHLventil AS gVent_pr,     avgHLGVSopenFlow+avgHLGVSopenRet+avgHLGVScloseParall+avgHLGVScloseMix+avgHLGVScloseConseq+avgHLGVSclosePreON AS gGvs_pr,     avgHLGVSopenFlow+avgHLGVSopenRet AS gGvsOpen_pr,     IIF(hlm.useTableData=0, rc.volWaterHS, hlm.volWaterHS) AS volWaterHS,     IIF(hlm.useTableData=0, rc.volWaterVS, hlm.volWaterVS) AS volWaterVS,     hlm.volWaterOpenGvs   FROM realConsumers2 rc   JOIN nodes n ON n.id = rc.nodeID   LEFT JOIN externalCodes ec on ec.id = n.externalCodeID   left join externalCodes ecm on ec.belongMagistral = ecm.id AND ec.objectID=2   JOIN heatLosesMainFact hlm ON hlm.id=1   WHERE n.removed=0 ;
