SET QUOTED_IDENTIFIER ON
GO

create view [dbo].[tempSezonView] as   SELECT     heatSourceID,     IIF(sezon=1, 14, 15) AS r,     IIF(sezon=1, 13, 14) AS m,     sezon,      sum(tn*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tn,     sum(tpod*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tpod,     sum(tgr*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tgr,     sum(tgP*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tgP,     sum(tgO*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tgO,     sum(tx*workCount)/sum(IIF(workCount = 0, 1, workCount)) AS tx,     sum(workCount) AS workCount   FROM   (     SELECT        hls.heatSourceID,       hls.r,        hls.m,        hls.sezon,        hl.tn,        hl.tpod,        hl.tgr,       hls.tgP,        hls.tgO,        hls.tx,        hls.workCount      FROM heatLosesSourceMonths hls     LEFT JOIN heatLoses hl     ON hls.m=hl.m      WHERE hls.heatSourceID IN (SELECT id FROM heatLosesSourceList)   ) _T1   GROUP BY     heatSourceID,     sezon ;
GO






CREATE FUNCTION [dbo].[getPts_remont2] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
select distinct
    pss.id as id,
    IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',CONCAT(nt1.name, ' ', n1.externalNodeName), n1.nodeName) as 'Наименование начального узла',
    IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',CONCAT(nt2.name, ' ', n2.externalNodeName), n2.nodeName) as 'Наименование конечного узла',
    rt.name as 'Вид ремонта',
    --st.name as 'Состояние',
    obj.data_nachala_remonta as 'Дата начала ремонтных работ',
    obj.data_zaversheniya_remonta as 'Дата завершения ремонтных работ',
    tubingTypes.name as 'Тип прокладки',
    faktory_riska_truboprovoda.len_tube as 'Длина заменённой трубы, м',
    faktory_riska_truboprovoda.len_channel as 'Восстановление канальной прокладки, м',
    faktory_riska_truboprovoda.diameterCondit as 'Диаметр условный, заменённой трубы, м',
    faktory_riska_truboprovoda.diameterInternal as 'Диаметр внутренний, заменённой трубы, м',
    faktory_riska_truboprovoda.diameterExternal as 'Диаметр наружный, заменённой трубы, м',
    faktory_riska_truboprovoda.wallThickness as 'Толщина стенки, , заменённой трубы, мм',
    faktory_riska_truboprovoda.len_izol as 'Восстановление тепловой изоляции поверхности трубы, м2',
    faktory_riska_truboprovoda.asfaltirovanie as 'Асфальтирование, ремонт, м2',
    'Перечень работ (трубопровода)' = STUFF(
                (
                    SELECT
                        concat(',', rtt2.name) AS n
                    FROM
                        faktory_riska_truboprovoda r2
                        LEFT JOIN remontCapitalTube rt2 ON r2.id = rt2.objID
                        LEFT JOIN remontCapitalTubeTypes rtt2 ON rtt2.id = rt2.activityID
                    WHERE
                        r2.id = obj.id FOR XML PATH(''),
                        TYPE
                ).value('.', 'NVARCHAR(MAX)'),
                1,
                1,
                ''
            ),
            'Перечень работ (канал)' = STUFF(
                (
                    SELECT
                        concat(',', rtt2.name) AS n
                    FROM
                        faktory_riska_truboprovoda r2
                        LEFT JOIN remontChannel rt2 ON r2.id = rt2.objID
                        LEFT JOIN remontChannelTypes rtt2 ON rtt2.id = rt2.activityID
                    WHERE
                        r2.id = obj.id FOR XML PATH(''),
                        TYPE
                ).value('.', 'NVARCHAR(MAX)'),
                1,
                1,
                ''
            ),
            'Перечень работ (камеры)' = STUFF(
                (
                    SELECT
                        concat(',', rtt2.name) AS n
                    FROM
                        faktory_riska_truboprovoda r2
                        LEFT JOIN remontKamera rt2 ON r2.id = rt2.objID
                        LEFT JOIN remontChannelTypes rtt2 ON rtt2.id = rt2.activityID
                    WHERE
                        r2.id = obj.id FOR XML PATH(''),
                        TYPE
                ).value('.', 'NVARCHAR(MAX)'),
                1,
                1,
                ''
    ),
    obj.nomer_prikaza as 'Номер приказа на ввод в эксплуатацию',
    format(obj.data_prikaza_vvoda_v_ekspluataciyu,'dd.MM.yyyy') as 'Дата приказа ввода в эксплуацию',
    sb.name as 'Подразделение производившее ремонт',
    nu.fio as 'Ответственный за ремонт'
   -- obj.id AS 'Номер контура'
from remont2 obj
    join remont2Deployed d on d.directionID = obj.id
    JOIN heatPipeSections hpss ON hpss.lineID=d.lineID
    JOIN pipeSections pss ON pss.id=hpss.pipeSectionID
    join linesobj l on l.id = d.lineID
    JOIN nodes n1 ON n1.id=pss.nodeID1
    JOIN nodes n2 ON n2.id=pss.nodeID2
    left join externalCodes ec1 ON ec1.id = n1.externalCodeID
    left join externalCodes ec2 ON ec2.id = n2.externalCodeID
    LEFT JOIN nodeTypes nt1 ON nt1.id=n1.nodeTypeID
    LEFT JOIN nodeTypes nt2 ON nt2.id=n2.nodeTypeID

    left join remontTypes rt on rt.id = obj.remontTypeID
    left join stateRemont2 st on st.id = obj.stateID
    left join subdivisions sb on sb.id = obj.subdivisionID
    --  left join responsibles rs on rs.id = obj.responsibleID
    left join nachalniki_uchastkov nu on nu.id = obj.responsibleID
    left join faktory_riska_truboprovoda on faktory_riska_truboprovoda.lineID = pss.id and faktory_riska_truboprovoda.objID = obj.id and faktory_riska_truboprovoda.obj_type_faktory_riskaID = 3
    left join tubingTypes on tubingTypes.id = pss.tubingTypeID

    left join uchastok_ms ms ON ms.id = pss.magistralSite
    left join uchastki_ekspluatatsii ue_ms ON ue_ms.id = ms.nomer_uchastka
    left join nachalniki_uchastkov nu_ms ON nu_ms.id = ue_ms.nachalnik_uchastka

    left join uchastok_rs rs ON rs.id = pss.distSite
    left join uchastki_ekspluatatsii ue_rs ON ue_rs.id = rs.nomer_uchastka
    left join nachalniki_uchastkov nu_rs ON nu_rs.id = ue_rs.nachalnik_uchastka

    where obj.stateID = 3 and n1.fileID in (select value from fn_split_string(@fragment, ','))
    AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
    and ( (@type = 'ms' and ms.id = @id) or (@type = 'rs' and rs.id = @id) or (@type = 'all'))
);

GO



CREATE FUNCTION [dbo].[getPts_osmotr] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
SELECT
    DISTINCT
            pss.id as 'id',
            IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',CONCAT(nt1.name, ' ', n1.externalNodeName), n1.nodeName) as 'Наименование начального узла',
            IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',CONCAT(nt2.name, ' ', n2.externalNodeName), n2.nodeName) as 'Наименование конечного узла',
            pss.DiamUslov as 'Диаметр трубопровода, мм',
            es.name as 'Признак участка трубопровода',
            obj.data_osmotra as 'Дата осмотра',
            vneshny_vid.name as 'Внешний вид',
            sost_oborud.name as 'Состояние оборудования',
            sostoyanie_metalla_truboprovoda.name as 'Состояние металла трубопровода',
            sost_konstr.name as 'Состояние строительных конструкций',
            sostoyanie_teplovoj_izolyacii_obratka.name as 'Состояние тепловой изоляции (обратный трубопровод)',
            sostoyanie_teplovoj_izolyacii_podacha.name as 'Состояние тепловой изоляции (подающий трубопровод)',
            sostoyanie_naruzhnogo_pokrytiya_obratka.name as 'Состояние наружного покрытия (обратный трубопровод)',
            sostoyanie_naruzhnogo_pokrytiya_podacha.name as 'Состояние наружного покрытия (подающий трубопровод)',
            sostoyanie_protivokorrozionnogo_pokrytiya_obratka.name as 'Состояние противокоррозионного покрытия (обратный трубопровод)',
            sostoyanie_protivokorrozionnogo_pokrytiya_podacha.name as 'Состояние противокоррозионного покрытия (подающий трубопровод)',
            otv.fio as 'Отвественное лицо',
            subd.name as 'Подразделение проводившее работу',
            IIF (ms.opisanie_uchastka_ms is not NULL, ms.opisanie_uchastka_ms, rs.naimenovanie_uchastka_rs) as 'Участок эксплуатации',
            IIF (nu_ms.fio is not NULL, nu_ms.fio, nu_rs.fio) as 'Начальник участка',
            --tubingTypes.name as 'Тип прокладки',
            --pss.pipeLength AS 'Длина участка теплопровода, м',
            srt.orderID,
            obj.id as 'objID'
        from osmotr obj
        join osmotrDeployed d on d.directionID = obj.id
        JOIN heatPipeSections hpss ON hpss.lineID=d.lineID
        JOIN pipeSections pss ON pss.id=hpss.pipeSectionID
        LEFT JOIN sortLinesForUchastok srt ON pss.id = srt.pipeSectionID
        LEFT join linesobj l on l.id = d.lineID

        left join faktory_riska_truboprovoda on faktory_riska_truboprovoda.lineID = pss.id and faktory_riska_truboprovoda.objID = obj.id and faktory_riska_truboprovoda.obj_type_faktory_riskaID = 2
        LEFT JOIN tubingTypes tt ON pss.tubingTypeID = tt.id
        left join sostoyanie_teplovoj_izolyacii sostoyanie_teplovoj_izolyacii_obratka on sostoyanie_teplovoj_izolyacii_obratka.id = faktory_riska_truboprovoda.sostoyanie_teplovoj_izolyacii_obratkaID
        left join sostoyanie_teplovoj_izolyacii sostoyanie_teplovoj_izolyacii_podacha on sostoyanie_teplovoj_izolyacii_podacha.id = faktory_riska_truboprovoda.sostoyanie_teplovoj_izolyacii_podachaID
        left join sostoyanie_naruzhnogo_pokrytiya sostoyanie_naruzhnogo_pokrytiya_obratka on sostoyanie_naruzhnogo_pokrytiya_obratka.id = faktory_riska_truboprovoda.sostoyanie_naruzhnogo_pokrytiya_obratkaID
        left join sostoyanie_naruzhnogo_pokrytiya sostoyanie_naruzhnogo_pokrytiya_podacha on sostoyanie_naruzhnogo_pokrytiya_podacha.id = faktory_riska_truboprovoda.sostoyanie_naruzhnogo_pokrytiya_podachaID
        left join sostoyanie_protivokorrozionnogo_pokrytiya_shurf sostoyanie_protivokorrozionnogo_pokrytiya_podacha on sostoyanie_protivokorrozionnogo_pokrytiya_podacha.id = faktory_riska_truboprovoda.sostoyanie_protivokorrozionnogo_pokrytiya_podachaID
        left join sostoyanie_protivokorrozionnogo_pokrytiya_shurf sostoyanie_protivokorrozionnogo_pokrytiya_obratka on sostoyanie_protivokorrozionnogo_pokrytiya_obratka.id = faktory_riska_truboprovoda.sostoyanie_protivokorrozionnogo_pokrytiya_obratkaID
        JOIN nodes n1 ON n1.id=pss.nodeID1
        JOIN nodes n2 ON n2.id=pss.nodeID2
        LEFT JOIN nodeTypes nt1 ON nt1.id=n1.nodeTypeID
        LEFT JOIN nodeTypes nt2 ON nt2.id=n2.nodeTypeID
        left join externalCodes ec1 ON ec1.id = n1.externalCodeID
        left join externalCodes ec2 ON ec2.id = n2.externalCodeID
        left join externalSigns  es on es.id = l.externalSignLineID

        LEFT JOIN tubingTypes ON tubingTypes.id=pss.tubingTypeID
        left join vneshny_vid on vneshny_vid.id=faktory_riska_truboprovoda.VnesniiVid
        left join sost_oborud on sost_oborud.id=faktory_riska_truboprovoda.SostOborudovania
        left join sost_konstr on sost_konstr.id=faktory_riska_truboprovoda.SostKonstrukz
        left join sostoyanie_metalla_truboprovoda on sostoyanie_metalla_truboprovoda.id = faktory_riska_truboprovoda.sostoyanie_metalla_truboprovodaID


        left join uchastok_ms ms ON ms.id = pss.magistralSite
        left join uchastki_ekspluatatsii ue_ms ON ue_ms.id = ms.nomer_uchastka
        left join nachalniki_uchastkov nu_ms ON nu_ms.id = ue_ms.nachalnik_uchastka

        left join uchastok_rs rs ON rs.id = pss.distSite
        left join uchastki_ekspluatatsii ue_rs ON ue_rs.id = rs.nomer_uchastka
        left join nachalniki_uchastkov nu_rs ON nu_rs.id = ue_rs.nachalnik_uchastka

        left join nachalniki_uchastkov otv ON otv.id = obj.otvetstvennoe_lico_ID
        left join subdivisions subd ON subd.id = obj.podrazdelenie_provodivshee_raboty

    where
    faktory_riska_truboprovoda.id IS not NULL and
    n1.fileID in (select value from fn_split_string(@fragment, ','))
    AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
    and ( (@type = 'ms' and ms.id = @id) or (@type = 'rs' and rs.id = @id) or (@type = 'all'))
);

GO


CREATE FUNCTION [dbo].[getPts_test] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
select
    distinct
     IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'Наименование начального узла',
     IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'Наименование конечного узла',
     obj.opisaniye_kontura as 'Описание контура',
     ot.name as 'Вид испытания',
     obj.date_opres as 'Дата проведения опрессовки',
     obj.davlenie_opressovki_1_etap as 'Давление опрессовки 1 этапа, кгс/см2',
     obj.davlenie_opressovki_2_etap as 'Давление опрессовки 2 этапа, кгс/см2',
     obj.reshenie_komissii as 'Решение комиссии',
     CONCAT(st.name, '', d.nomer_doma) as 'Адрес нарушения',
     d.defectDescription as 'Описание повреждения',
     d.meropriyatiya as 'Способ ликвидации нарушения',
     obj.fio_rukovoditel_ispytanij as 'ФИО руководителя испытаний',
     dolzhnosti_ruk.znachenie as 'Должность руководителя испытаний',
     subd_ruk.name as 'Подразделение руководителя испытаний',
     IIF (ms.opisanie_uchastka_ms is not NULL, ms.opisanie_uchastka_ms, rs.naimenovanie_uchastka_rs) as 'Участок эксплуатации',
     IIF (nu_ms.fio is not NULL, nu_ms.fio, nu_rs.fio) as 'ФИО начальника участка',
     obj.id as 'obj_id',
     d.id as 'defect_id',
     ms.id as 'msID',
     rs.id as 'rsID',
     nf.fileID as 'fileID'
from opres obj
    left join opresDeployed od ON od.directionID = obj.id
    left join linesobj l on l.id = od.lineID
    LEFT JOIN heatPipeSections hps ON hps.lineID = l.id
    left join pipeSections pss on pss.id = hps.pipeSectionID
    LEFT JOIN sortLinesForUchastok srt ON hps.pipeSectionID = srt.pipeSectionID
    LEFT JOIN nodes n1 ON n1.id = pss.nodeID1
    LEFT JOIN nodes n2 ON n2.id = pss.nodeID2
    left join externalCodes ec1 ON ec1.id = n1.externalCodeID
    left join externalCodes ec2 ON ec2.id = n2.externalCodeID
    left join opres_types ot on ot.id = obj.opres_typeID
    left join defect d ON l.shape.STDistance(d.shape.STPointN(1)) < 0.3 and d.opresID = obj.id
    left join ulitsy st ON st.id = d.ulicaID
    left join nodes nf on nf.id = l.nodeID1
    left join vid_ispytani vid_is on vid_is.id = obj.vid_ispytaniID
    LEFT JOIN dolzhnosti dolzhnosti_ruk ON dolzhnosti_ruk.id = obj.dolzhnost_rukovoditel_ispytanijID
    LEFT JOIN subdivisions subd_ruk ON subd_ruk.id = obj.podrazdelenie_rukovoditel_ispytanijID

    left join uchastok_ms ms ON ms.id = pss.magistralSite
    left join uchastki_ekspluatatsii ue_ms ON ue_ms.id = ms.nomer_uchastka
    left join nachalniki_uchastkov nu_ms ON nu_ms.id = ue_ms.nachalnik_uchastka

    left join uchastok_rs rs ON rs.id = pss.distSite
    left join uchastki_ekspluatatsii ue_rs ON ue_rs.id = rs.nomer_uchastka
    left join nachalniki_uchastkov nu_rs ON nu_rs.id = ue_rs.nachalnik_uchastka
    where obj.sostoyanie_opresID = 3 and nf.fileID in (select value from fn_split_string(@fragment, ','))
    AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
    and ( (@type = 'ms' and ms.id = @id) or (@type = 'rs' and rs.id = @id) or (@type = 'all'))
);


GO



-- Функция возвращает таблицу для паспорта Ф12

CREATE FUNCTION [dbo].[getPts_shurf] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
select distinct top 2147483647
    t.obj_id as id,
    IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'Наименование начального узла',
    IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'Наименование конечного узла',
    es.name as 'Признак участка трубопровода',
    hpss.diameterExternal as 'Диаметр трубопровода, мм',
    n_vskr.name as 'Назначение вскрытия',
    CONCAT(st.name,' ',t.nomer_doma) as 'Адрес',
    sost_shurf.name as 'Состояние',
    t.data_nachala as 'Дата начала',
    t.data_okonchaniya as 'Дата окончания',
    t.nomer_akta as 'Номер акта',
    t.rezultaty_osmotra as 'Результаты осмотра',
    t.primechanie as 'Примечание',
    t.fio_utverzhdaemogo as 'ФИО утверждающего',
    dolz.znachenie as 'Должность утверждающего',
    subd.name as 'Служба утверждающего',
    IIF (pss.magistralSite is not NULL, re_ms.naimenovanie_rayona_ekspluatatsii_istochnika_tepla, re_rs.naimenovanie_rayona_ekspluatatsii_istochnika_tepla) as 'Участок эксплуатации',
    IIF (nu_ms.fio is not NULL, nu_ms.fio, nu_rs.fio) as 'ФИО начальника участка',
    srt.orderID
from(
    select distinct
        l.lineID,
        l.externalSignLineID,
        d.id as obj_id,
        d.materialy_i_mekhanizmyID,
        d.data_utverzhdeniya_plana_shurfovok,
        d.naznachenie_vskrID,
        d.ulicaID,
        d.nomer_doma,
        d.sostoyanie_shurfaID,
        d.data_nachala_plan,
        d.data_okonchaniya_plan,
        d.data_nachala,
        d.data_okonchaniya,
        d.rasstoyanie_do_blizhajshej_kamery,
        d.nodeID_bizhajshej_kamery,
        d.dlina_osmotra,
        d.glubina_zalozheniya,
        d.nomer_akta,
        d.predpolagaemye_prichiny_razrusheniya_izolyacii,
        d.rezultaty_osmotra,
        d.namechennye_meropriyatiya,
        d.meropriyatiya_po_vosstanovleniyu_prokladki,
        d.primechanie,
        d.fio_utverzhdaemogo,
        d.dolzhnost_utverzhdaemogoID,
        d.sluzhba_utverzhdaemogoID,
        d.fio_1,
        d.dolzhnost_1,
        d.fio_2,
        d.dolzhnost_2,
        d.fio_viziruemogo_1,
        d.dolzhnost_viziruemogoID_1
    from shurfy d
        JOIN (
            select
                k.lineID,
                k.externalSignLineID,
                k.obj_id
            from (
                select
                    distinct
                        l.id as lineID,
                        d.id as obj_id,
                        l.externalSignLineID,
                        l.shape.STDistance(d.shape.STPointN(1)) as length,
                        MIN(l.shape.STDistance(d.shape.STPointN(1))) OVER(PARTITION BY d.id ) AS "min_len"
                from shurfy d
                JOIN linesobj l ON ( l.removed = 0 and l.shape.STDistance(d.shape.STPointN(1)) < 0.3 )
                where d.utverdit != 0
            )k
        where k.min_len = k.length
    ) l on l.obj_id = d.id
)t
    LEFT JOIN heatPipeSections hpss ON hpss.lineID=t.lineID
    LEFT JOIN pipeSections pss ON pss.id = hpss.pipeSectionID
    LEFT JOIN sortLinesForUchastok srt ON srt.pipeSectionID = pss.id
    left JOIN nodes n1 ON ( n1.id = pss.nodeID1 and n1.removed = 0 )
    LEFT JOIN nodes n2 ON n2.id = pss.nodeID2
    left join externalSigns  es on es.id = t.externalSignLineID
    left join externalCodes ec1 ON ec1.id = n1.externalCodeID
    left join externalCodes ec2 ON ec2.id = n2.externalCodeID


    left join uchastok_ms ms ON ms.id = pss.magistralSite
    left join uchastki_ekspluatatsii ue_ms ON ue_ms.id = ms.nomer_uchastka

    left join rayon_ekspluatatsii re_ms ON re_ms.id = ue_ms.rayon_ekspluatatsii
    left join nachalniki_uchastkov nu_ms ON nu_ms.id = ue_ms.nachalnik_uchastka

    left join uchastok_rs rs ON rs.id = pss.distSite
    left join uchastki_ekspluatatsii ue_rs ON ue_rs.id = rs.nomer_uchastka

    left join rayon_ekspluatatsii re_rs ON re_rs.id = ue_rs.rayon_ekspluatatsii
    left join nachalniki_uchastkov nu_rs ON nu_rs.id = ue_rs.nachalnik_uchastka

    left join ulitsy st ON st.id = t.ulicaID
    left join sostoyanie_shurfa sost_shurf on sost_shurf.id = t.sostoyanie_shurfaID
    left join naznachenie_vskr n_vskr ON n_vskr.id = t.naznachenie_vskrID

    LEFT JOIN dolzhnosti dolz ON dolz.id=t.dolzhnost_utverzhdaemogoID
    LEFT JOIN subdivisions subd ON subd.id=t.sluzhba_utverzhdaemogoID

where   n1.fileID in (select value from fn_split_string(@fragment, ','))
        and  ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
        and (
                (@type = 'ms' and  pss.magistralSite = @id)
                or (@type = 'rs' and pss.distSite = @id)
                or (@type = 'pipe' and pss.id = @id )
                or (@type = 'all')
            )

order by t.data_nachala desc
);

GO

-- Функция возвращает таблицу для паспорта Ф11

CREATE    FUNCTION [dbo].[getPts_defect] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
select distinct top 2147483647
    t.[Наименование начального узла],
    t.[Наименование конечного узла],
    t.[Режим],
    t.[Состояние],
    t.[Дата обнаружения нарушения],
    t.[Адрес],
    t.[Описание повреждения],
    t.[Вид нарушения],
    t.[Категория нарушения],
    t.[Способ ликвидации нарушения],
    t.[Дата начала ремонтных работ],
    t.[Дата завершения ремонтных работ],
    t.workListTube as 'Ремонт трубопровода и элементов',
    t.len_tube as 'Длина заменённой трубы, м',
    t.len_izol as 'Длина заменённой изоляции, м',
    t.workListChannel as 'Ремонт канала',
    t.workListKamera as 'Ремонт камеры',
    t.len_channel as 'Длина участка ремонта канала',
    t.subdivision as 'Подразделение производившего работы',
    t.dolzhnost as 'Должность ответственного',
    t.fio_otv as 'ФИО ответственного',
    t.naimenovanie_uchastka as 'Участок эксплуатации',
    t.fio as 'ФИО',
    t.primechanie,
    t.orderID,
    t.id as 'id_obj',
    t.length,
    t.min_len,
    t.ms,
    t.rs
    FROM (
     SELECT
      IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'Наименование начального узла',
      IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'Наименование конечного узла',
      deft.name as 'Режим',
      stateDefect.name as 'Состояние',
      FORMAT(obj.data_osmotra,'dd.MM.yyyy' ) as 'Дата обнаружения нарушения',
      obj.vremya_osmotra as 'Время обнаружения повреждения',
      CONCAT(st.name, '', obj.nomer_doma) as 'Адрес',
      obj.defectDescription as 'Описание повреждения',
      vn.code as 'Вид нарушения',
      rc.name as 'Категория нарушения',
      obj.meropriyatiya as 'Способ ликвидации нарушения',
      obj.data_nachala_remonta as 'Дата начала ремонтных работ',
      obj.data_zaversheniya_remonta as 'Дата завершения ремонтных работ',

      workListTube = STUFF(
        (
            SELECT
                distinct concat(
                    IIF( rtt2.name != '', CONCAT(', ', rtt2.name, ':'),''),
                    STUFF (
                        (
                            select
                                concat(',', se.name) as n
                            from
                                defectTube dt
                                LEFT JOIN spisokElementov se ON se.id = dt.elementID
                            where
                                objId = obj.id
                                and activityID = rt2.activityID FOR XML PATH(''),
                                TYPE
                        ).value('.', 'NVARCHAR(MAX)'), 1, 1, ''
                    )
                ) AS n
            FROM
                defect r2
                left JOIN defectTube rt2 ON r2.id = rt2.objID
                left JOIN remontTruboprovodaSpisok rtt2 ON rtt2.id = rt2.activityID
            WHERE
                r2.id = obj.id FOR XML PATH(''),
                TYPE
        ).value('.', 'NVARCHAR(MAX)'), 1, 1, ''
      ),
      remont_kanala.name as workListChannel,
      remont_kamery.name as workListKamera,
      obj.len_tube_cur AS len_tube,
      obj.len_izol_cur AS len_izol,
      obj.len_channel_cur AS len_channel,
      obj.primechanie,
      subd.name as subdivision,
      d.znachenie as dolzhnost,
      nach.fio as fio_otv,
      IIF (ms.opisanie_uchastka_ms is not NULL, ms.opisanie_uchastka_ms, rs.naimenovanie_uchastka_rs) as naimenovanie_uchastka,
      IIF (nu_ms.fio is not NULL, nu_ms.fio, nu_rs.fio) as fio,
      l.shape.STDistance(obj.shape.STPointN(1)) as length,
      MIN(l.shape.STDistance(obj.shape.STPointN(1))) OVER(PARTITION BY obj.id ) AS "min_len",
      obj.id,
      srt.orderID,
      pss.magistralSite as 'ms',
      pss.distSite as 'rs'
FROM defect obj
LEFT JOIN linesobj l ON l.shape.STDistance(obj.shape.STPointN(1)) < 0.3
LEFT JOIN heatPipeSections hps ON hps.lineID=l.id
left join pipeSections pss on pss.id = hps.pipeSectionID
LEFT JOIN sortLinesForUchastok srt ON hps.pipeSectionID = srt.pipeSectionID
LEFT JOIN nodes n1 ON n1.id = pss.nodeID1
LEFT JOIN nodes n2 ON n2.id = pss.nodeID2
left join externalCodes ec1 ON ec1.id = n1.externalCodeID
left join externalCodes ec2 ON ec2.id = n2.externalCodeID
left join ulitsy st ON st.id = obj.ulicaID
left join vid_narusheniya vn on vn.id = obj.vid_narusheniyaID
LEFT JOIN defectTypes deft ON deft.id = obj.remontTypeID
left join remont_kanala on remont_kanala.id = obj.remont_kanalaID
left join remont_kamery on remont_kamery.id = obj.remont_kameryID
left join stateDefect on stateDefect.id = obj.stateID
LEFT JOIN remontCat rc ON rc.id = obj.remontCatID
LEFT JOIN nachalniki_uchastkov nach ON nach.id=obj.responsibleID
LEFT JOIN dolzhnosti d ON d.id=nach.dolzhnost
LEFT JOIN subdivisions subd ON subd.id=subdivisionID
left join uchastok_ms ms ON ms.id = hps.magistralSite
left join uchastki_ekspluatatsii ue_ms ON ue_ms.id = ms.nomer_uchastka
left join nachalniki_uchastkov nu_ms ON nu_ms.id = ue_ms.nachalnik_uchastka
--left join rayon_ekspluatatsii re_ms ON re_ms.id = ue_ms.rayon_ekspluatatsii
left join uchastok_rs rs ON rs.id = hps.distSite
left join uchastki_ekspluatatsii ue_rs ON ue_rs.id = rs.nomer_uchastka
left join nachalniki_uchastkov nu_rs ON nu_rs.id = ue_rs.nachalnik_uchastka

WHERE NOT l.shape.STDistance(obj.shape.STPointN(1)) IS NULL
        and n1.fileID in (select value from fn_split_string(@fragment, ','))
        AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
        and ( (@type = 'ms' and pss.magistralSite = @id)
        or (@type = 'rs' and pss.distSite= @id)
        or (@type = 'pipe' and pss.id = @id ) )
) t
where t.length = t.min_len );

GO



-- Функция возвращает таблицу для паспорта Ф12

CREATE FUNCTION [dbo].[getPts_cut_out] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
select distinct top 2147483647
    t.obj_id as id,
    IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'Наименование начального узла',
    IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'Наименование конечного узла',
    es.name as 'Признак участка трубопровода',
    hpss.diameterExternal as 'Диаметр трубопровода, мм',
    n_vskr.name as 'Назначение вскрытия',
    CONCAT(st.name,' ',t.nomer_doma) as 'Адрес',
    sost_shurf.name as 'Состояние',
    t.data_nachala as 'Дата начала',
    t.data_okonchaniya as 'Дата окончания',
    t.nomer_akta as 'Номер акта',
    t.rezultaty_osmotra as 'Результаты осмотра',
    sostoyanie_metalla_truboprovoda.name as 'Состояние металла трубопровода',
    faktRiska_7_vneshkorroz.name as 'Cтепень внешней коррозии',
    faktRiska_8_vnutkorroz.name as 'Степень внутренней коррозии',
    t.primechanie as 'Примечание',
    t.fio_utverzhdaemogo as 'ФИО утверждающего',
    dolz.znachenie as 'Должность утверждающего',
    subd.name as 'Служба утверждающего',
    IIF (pss.magistralSite is not NULL, re_ms.naimenovanie_rayona_ekspluatatsii_istochnika_tepla, re_rs.naimenovanie_rayona_ekspluatatsii_istochnika_tepla) as 'Участок эксплуатации',
    IIF (nu_ms.fio is not NULL, nu_ms.fio, nu_rs.fio) as 'ФИО начальника участка',
    srt.orderID
from(
    select distinct
        l.lineID,
        l.externalSignLineID,
        d.id as obj_id,
        d.materialy_i_mekhanizmyID,
        d.data_utverzhdeniya_plana_shurfovok,
        d.naznachenie_vskrID,
        d.ulicaID,
        d.nomer_doma,
        d.sostoyanie_shurfaID,
        d.data_nachala_plan,
        d.data_okonchaniya_plan,
        d.data_nachala,
        d.data_okonchaniya,
        d.rasstoyanie_do_blizhajshej_kamery,
        d.nodeID_bizhajshej_kamery,
        d.dlina_osmotra,
        d.glubina_zalozheniya,
        d.nomer_akta,
        d.predpolagaemye_prichiny_razrusheniya_izolyacii,
        d.rezultaty_osmotra,
        d.namechennye_meropriyatiya,
        d.meropriyatiya_po_vosstanovleniyu_prokladki,
        d.primechanie,
        d.fio_utverzhdaemogo,
        d.dolzhnost_utverzhdaemogoID,
        d.sluzhba_utverzhdaemogoID,
        d.fio_1,
        d.dolzhnost_1,
        d.fio_2,
        d.dolzhnost_2,
        d.fio_viziruemogo_1,
        d.dolzhnost_viziruemogoID_1
    from shurfy d
        JOIN (
            select
                k.lineID,
                k.externalSignLineID,
                k.obj_id
            from (
                select
                    distinct
                        l.id as lineID,
                        d.id as obj_id,
                        l.externalSignLineID,
                        l.shape.STDistance(d.shape.STPointN(1)) as length,
                        MIN(l.shape.STDistance(d.shape.STPointN(1))) OVER(PARTITION BY d.id ) AS "min_len"
                from shurfy d
                JOIN linesobj l ON ( l.removed = 0 and l.shape.STDistance(d.shape.STPointN(1)) < 0.3 )
                where d.utverdit != 0
            )k
        where k.min_len = k.length
    ) l on l.obj_id = d.id
)t
    LEFT JOIN heatPipeSections hpss ON hpss.lineID=t.lineID
    LEFT JOIN pipeSections pss ON pss.id = hpss.pipeSectionID
    LEFT JOIN sortLinesForUchastok srt ON srt.pipeSectionID = pss.id
    left JOIN nodes n1 ON ( n1.id = pss.nodeID1 and n1.removed = 0 )
    LEFT JOIN nodes n2 ON n2.id = pss.nodeID2
    left join externalSigns  es on es.id = t.externalSignLineID
    left join externalCodes ec1 ON ec1.id = n1.externalCodeID
    left join externalCodes ec2 ON ec2.id = n2.externalCodeID
    join faktory_riska_truboprovoda on faktory_riska_truboprovoda.lineID = pss.id and faktory_riska_truboprovoda.objID = t.obj_id and faktory_riska_truboprovoda.obj_type_faktory_riskaID = 1

    left join faktRiska_7_vneshkorroz on faktRiska_7_vneshkorroz.id = faktory_riska_truboprovoda.VnesnKorrozia
    left join faktRiska_8_vnutkorroz on faktRiska_8_vnutkorroz.id = faktory_riska_truboprovoda.VnunrenKorrozia
    left join sostoyanie_metalla_truboprovoda on sostoyanie_metalla_truboprovoda.id = faktory_riska_truboprovoda.sostoyanie_metalla_truboprovodaID

    left join uchastok_ms ms ON ms.id = pss.magistralSite
    left join uchastki_ekspluatatsii ue_ms ON ue_ms.id = ms.nomer_uchastka

    left join rayon_ekspluatatsii re_ms ON re_ms.id = ue_ms.rayon_ekspluatatsii
    left join nachalniki_uchastkov nu_ms ON nu_ms.id = ue_ms.nachalnik_uchastka

    left join uchastok_rs rs ON rs.id = pss.distSite
    left join uchastki_ekspluatatsii ue_rs ON ue_rs.id = rs.nomer_uchastka

    left join rayon_ekspluatatsii re_rs ON re_rs.id = ue_rs.rayon_ekspluatatsii
    left join nachalniki_uchastkov nu_rs ON nu_rs.id = ue_rs.nachalnik_uchastka

    left join ulitsy st ON st.id = t.ulicaID
    left join sostoyanie_shurfa sost_shurf on sost_shurf.id = t.sostoyanie_shurfaID
    left join naznachenie_vskr n_vskr ON n_vskr.id = t.naznachenie_vskrID

    LEFT JOIN dolzhnosti dolz ON dolz.id=t.dolzhnost_utverzhdaemogoID
    LEFT JOIN subdivisions subd ON subd.id=t.sluzhba_utverzhdaemogoID

where   n1.fileID in (select value from fn_split_string(@fragment, ','))  and
        (faktRiska_7_vneshkorroz.id is not null  or faktRiska_8_vnutkorroz.id is not null or sostoyanie_metalla_truboprovoda.id is not null)
        and  ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
        and (
                (@type = 'ms' and  pss.magistralSite = @id)
                or (@type = 'rs' and pss.distSite = @id)
                or (@type = 'pipe' and pss.id = @id )
                or (@type = 'all')
            )

order by t.data_nachala desc
);

GO


-- Функция возвращает таблицу для паспорта Ф2_1
CREATE FUNCTION [dbo].[getPts] (@id int, @type varchar(20), @fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
    SELECT
    distinct
    t.tblName,
    t.beginNode,
    t.endNode,
    t.externalID,
    t.armatureType,
    t.designType,
    t.constructionType,
    t.material,
    t.diametr,
    1 as 'count_obj',
    t.orderID,
    t.externalID2,
    t.purposeType,
    IIF( t.min_node1 < t.min_node2, t.beginNode, t.endNode) as pavilion,
    t.id as 'id_obj',
    t.pipeSectionID,
    t.externalLineStr,
    t.ms,
    t.rs
    FROM (
        SELECT
            IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'beginNode',
            IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'endNode',
            l.shape.STDistance(obj.shape.STPointN(1)) as length,
            MIN(l.shape.STDistance(obj.shape.STPointN(1))) OVER(PARTITION BY obj.id ) AS "min_len",
            MIN(obj.shape.STPointN(1).STDistance(n1.shape)) OVER(PARTITION BY obj.id ) AS "min_node1",
            MIN(obj.shape.STPointN(1).STDistance(n2.shape)) OVER(PARTITION BY obj.id ) AS "min_node2",
            srt.orderID,
            obj.tblName,
            l.externalSignLineID as 'externalID',
            obj.priznak_truboprovoda as 'externalID2',
            arm_t.name as 'armatureType',
            des_t.name as 'designType',
            con_t.name as 'constructionType',
            mat_t.name as 'material',
            pur_t.name as 'purposeType',
            --n2.nodeName as 'pavilion',
            --nn.nodeName as 'pavilion',
            obj.diametr,
            obj.id,
            hps.magistralSite as 'ms',
            hps.distSite as 'rs',
            pss.id AS pipeSectionID,
            el.name as 'externalLineStr'
        FROM vtPtsAll obj
        LEFT JOIN linesobj l ON l.shape.STDistance(obj.shape.STPointN(1)) < 0.3
        LEFT JOIN externalSignLine el ON el.id = obj.priznak_truboprovoda
        LEFT JOIN heatPipeSections hps ON hps.lineID=l.id
        LEFT JOIN pipeSections pss ON pss.id=hps.pipeSectionID
        LEFT JOIN sortLinesForUchastok srt ON hps.pipeSectionID = srt.pipeSectionID
        LEFT JOIN purposeTypes pur_t ON pur_t.id = obj.purposeTypesID
        LEFT JOIN armatureTypes arm_t ON arm_t.id = obj.armatureTypesID
        LEFT JOIN designTypes des_t ON des_t.id = obj.designTypesID
        LEFT JOIN constructionTypes con_t ON con_t.id = obj.constructionTypesID
        LEFT JOIN materialTypes mat_t ON mat_t.id = obj.materialTypesID
        LEFT JOIN nodes n1 ON n1.id = pss.nodeID1
        LEFT JOIN nodes n2 ON n2.id = pss.nodeID2
        left join externalCodes ec1 ON ec1.id = n1.externalCodeID
        left join externalCodes ec2 ON ec2.id = n2.externalCodeID
        --LEFT JOIN nodes nn ON nn.shape.STDistance(obj.shape.STPointN(1)) < 3
        WHERE NOT l.shape.STDistance(obj.shape.STPointN(1)) IS NULL and n1.fileID in (select value from fn_split_string(@fragment, ',') )
        AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
        and (
            (@type = 'ms' and hps.magistralSite = @id)
            or (@type = 'rs' and hps.distSite = @id)
            or (@type = 'pipe' and pss.id = @id)
            or (@type = 'all')
            or (@type = 'obj' and obj.id = @id) )
        and l.externalSignLineID is not NULL
    ) as t
where   t.length = t.min_len
);



GO

-- Функция возвращает таблицу для паспорта Ф2_2

CREATE  FUNCTION [dbo].[getPts_kompensator_kolodtsy] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
    SELECT
    distinct
    t.tblName,
    t.beginNode,
    t.endNode,
    t.externalID,
    t.constructionTypes,
    t.diametr_truboprovoda,
    t.purposeTypes,
    t.characteristicTypes,
    t.characteristicTypesLyuki,
    t.materialTypesLyuki,
    t.constructionTypesLyuki,
    t.orderID,
    t.pavilion,
    t.pipeSectionID,
    t.externalLineStr,
    t.id_obj
     FROM (
        SELECT
        IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'beginNode',
        IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'endNode',
        l.shape.STDistance(obj.shape.STPointN(1)) as length,
        MIN(l.shape.STDistance(obj.shape.STPointN(1))) OVER(PARTITION BY obj.id ) AS "min_len",
        srt.orderID,
        obj.tblName,
        obj.priznak_truboprovoda as 'externalID',
        obj.diametr_truboprovoda,
        obj.purposeTypes,
        obj.characteristicTypes,
        obj.constructionTypes,
        obj.characteristicTypesLyuki,
        obj.materialTypesLyuki,
        obj.constructionTypesLyuki,
        n2.nodeName as 'pavilion',
        pss.id AS pipeSectionID,

        el.name as 'externalLineStr',
        obj.id as 'id_obj'
        FROM vtPassT2 obj
        LEFT JOIN linesobj l ON l.shape.STDistance(obj.shape.STPointN(1)) < 4
        LEFT JOIN externalSignLine el ON el.id = obj.priznak_truboprovoda
        LEFT JOIN heatPipeSections hps ON hps.lineID=l.id

        LEFT JOIN pipeSections pss ON pss.id=hps.pipeSectionID

        LEFT JOIN sortLinesForUchastok srt ON hps.pipeSectionID = srt.pipeSectionID
        LEFT JOIN nodes n1 ON n1.id = pss.nodeID1
        LEFT JOIN nodes n2 ON n2.id = pss.nodeID2

        left join externalCodes ec1 ON ec1.id = n1.externalCodeID
        left join externalCodes ec2 ON ec2.id = n2.externalCodeID
        WHERE NOT l.shape.STDistance(obj.shape.STPointN(1)) IS NULL
        and n1.fileID in (select value from fn_split_string(@fragment, ','))
        AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
        and (
            (@type = 'ms' and hps.magistralSite = @id)
            or (@type = 'rs' and hps.distSite = @id)
            or (@type = 'pipe' and pss.id = @id)
            or (@type = 'all')
            or (@type = 'obj' and obj.id = @id) )
    ) as t
where t.length = t.min_len
);

GO


-- Функция возвращает таблицу для паспорта Ф4
CREATE FUNCTION [dbo].[getPts_tkamera] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS  
RETURN
(
    SELECT 
    distinct
    t.tblName,
    --t.beginNode, 
    --t.endNode,
    t.pavilion,
    t.constructionType,
    t.height,
    t.lenKamera,    
    t.width,
    t.overlapType,
    t.constructionOverlapType,
    t.count_lyukov,
    t.nalichie_reshetok,
    t.god_vvoda,
    t.naimenovanie_uchastka,
    t.fio,
    t.organizations,
    t.primechanie,
    t.orderID,
    t.objID,
    t.fileID
  
    FROM (
        SELECT
        --IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'beginNode',
        --IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'endNode',       
        l.shape.STDistance(obj.shape) as length,        
        MIN(l.shape.STDistance(obj.shape)) OVER(PARTITION BY obj.id ) AS "min_len",
        IIF(obj.shape.STIntersects(n1.shape) = 1, IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName),IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName)) AS "pavilion",  
        srt.orderID,
        'Камера' as tblName,        
        ov.name as overlapType,
        cov.name as constructionOverlapType,
        ct.name as constructionType,
        vnutr_vysota_kamery as height,
        vnutr_shirina_kamery as width,
        vnutr_dlina_kamery as lenKamera,
        fakticheskoe_kolichestvo_lyukov as count_lyukov,
        nalichie_reshetok as nalichie_reshetok,
        god_vvoda_v_jekspluataciju as god_vvoda,
        IIF (ms.opisanie_uchastka_ms is not NULL, ms.opisanie_uchastka_ms, rs.naimenovanie_uchastka_rs) as naimenovanie_uchastka,
        IIF (nu_ms.fio is not NULL, nu_ms.fio, nu_rs.fio) as fio,
        n1.fileID,
        obj.primechanie,
        org.name as organizations,
        obj.id as 'objID',
        srt.id as 'srtID'
        FROM tkamera obj        
        LEFT JOIN linesobj l ON l.shape.STDistance(obj.shape) < 0.1
        LEFT JOIN heatPipeSections hps ON hps.lineID=l.id
        LEFT JOIN pipeSections pss ON pss.id = hps.pipeSectionID
        LEFT JOIN sortLinesForUchastok srt ON hps.pipeSectionID = srt.pipeSectionID
        LEFT JOIN nodes n1 ON n1.id = pss.nodeID1
        LEFT JOIN nodes n2 ON n2.id = pss.nodeID2
        left join externalCodes ec1 ON ec1.id = n1.externalCodeID
        left join externalCodes ec2 ON ec2.id = n2.externalCodeID   
        LEFT JOIN overlapTypes ov on ov.id = obj.overlapTypesID
        LEFT JOIN constructionOverlapTypes cov ON cov.id = obj.constructionOverlapTypesID
        LEFT JOIN constructionTypes ct on ct.id = obj.constructionTypesID
        left join organizations org on org.id = obj.organizationID
        left join uchastok_ms ms ON ms.id = pss.magistralSite
        left join uchastki_ekspluatatsii ue_ms ON ue_ms.id = ms.nomer_uchastka
        left join nachalniki_uchastkov nu_ms ON nu_ms.id = ue_ms.nachalnik_uchastka

        left join uchastok_rs rs ON rs.id = pss.distSite
        left join uchastki_ekspluatatsii ue_rs ON ue_rs.id = rs.nomer_uchastka
        left join nachalniki_uchastkov nu_rs ON nu_rs.id = ue_rs.nachalnik_uchastka
        WHERE NOT l.shape.STDistance(obj.shape) IS NULL
        and n1.fileID in (select value from fn_split_string(@fragment, ','))
        and  ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )    
        and ( 
            (@type = 'ms' and pss.magistralSite = @id) 
            or (@type = 'rs' and pss.distSite = @id) 
            or (@type = 'pipe' and pss.id = @id)
            or (@type = 'all')
            or (@type = 'obj' and obj.id = @id) )       
    ) as t
    where 
    t.length = t.min_len 
    --and ( t.data_zaversheniya_remonta = t.last_date_remont or t.last_date_remont is NULL)
     -- and (t.pavilion_is_null = t.objID)  
);



GO

-- Функции возвращает таблицу для паспорта Ф1.Труба
CREATE     FUNCTION [dbo].[getTubesPts] (@id int, @type varchar(20), @fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
    select
    distinct
    IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'beginPts',
    IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'endPts',
    l.externalSignLineID as externalID,
    MAX(hps.diameterExternal) over (partition by pss.id) d,
    MAX(hps.wallThickness) over (partition by pss.id) as wall,
    MAX(hps.pipeSectLength) over (partition by pss.id) as l,
    (SUM(hps.pipeSectLength) over (partition by pss.id) * POWER((MAX(hps.diameterInternal) over (partition by pss.id)/1000),2) * (PI()/4)) v,
    typeT.name type_tube,
    viewT.name kind_tube,
    max(srt.orderID) over (partition by pss.id) as orderID,
    n1.fileID
from pipeSections pss
    left join heatPipeSections hps on hps.pipeSectionID = pss.id
    left join linesobj l on l.id = hps.lineID
    left join sortLinesForUchastok srt on srt.pipeSectionID = pss.id
    LEFT JOIN nodes n1 ON n1.id = pss.nodeID1
    LEFT JOIN nodes n2 ON n2.id = pss.nodeID2
    left join externalCodes ec1 ON ec1.id = n1.externalCodeID
    left join externalCodes ec2 ON ec2.id = n2.externalCodeID
    left join tubeTypes viewT ON viewT.id = pss.tubeTypeID
    left join tubingTypes typeT ON typeT.id = pss.tubingTypeID
    where ( (@type = 'rs' and pss.distSite = @id) or (@type = 'ms' and pss.magistralSite = @id) ) and l.externalSignLineID is not NULL
    AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
    and n1.fileID in (select value from fn_split_string(@fragment, ','))
    and orderID is not null
)

GO

-- Функция возвращает таблицу для паспорта Ф3
CREATE FUNCTION [dbo].[getPts_kanal] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
    SELECT
    distinct
    t.tblName,
    t.beginNode,
    t.endNode,
    t.channelType,
    t.overlapType,
    t.width,
    t.height,
    t.d_hps,
    t.d_obj,
    t.constructionType,
    t.lenChannel,
    t.orderID,
    t.god_vvoda,
    t.last_date_remont,
    t.workListChannel,
    t.len_channel_remont,
    t.primechanie,
    t.fileID,
    t.objID,
    t.srtID,
    t.length,
    t.min_len
     FROM (
        SELECT
        IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'beginNode',
        IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'endNode',
        l.shape.STDistance(obj.shape) as length,
        MIN(l.shape.STDistance(obj.shape)) OVER(PARTITION BY obj.id ) AS "min_len",
        MAX(r.data_zaversheniya_remonta ) OVER(PARTITION BY obj.id ) as 'last_date_remont',
        MAX(srt.orderID) over (partition by obj.id) as orderID,
        MAX(srt.id) over (partition by obj.id) as 'srtID',
        'Канал' as tblName,
        ch.name as channelType,
        ov.name as overlapType,
        mt.name as materialType,
        obj.shirina__mm as width,
        obj.vysota__mm as height,
        pss.DiamUslov as d_hps,
        obj.diametr_truby__uslovnyy__mm as d_obj,
        ct.name as constructionType,
        obj.dlina__mm as lenChannel,
        n1.fileID,
        obj.primechanie,
        obj.id as 'objID',
        l.id as 'lineID',
        l.externalSignLineID,
        obj.god_vvoda_v_ekspluatatsiyu as 'god_vvoda',
        r.data_zaversheniya_remonta,
        workListChannel =  case r.remontTypeID
        when 1 then STUFF(
                        ( SELECT CHAR(10)+rtt2.name AS n FROM remont r2
                        LEFT JOIN remontInvestChannel rt2 ON r2.id=rt2.objID
                        LEFT JOIN remontInvestChannelTypes rtt2 ON rtt2.id=rt2.activityID
                        WHERE r2.id=r.id
                        FOR XML PATH('')
                        , TYPE
                        ).value('.', 'NVARCHAR(MAX)'), 1, 1, '')
          when 2 then   STUFF(
                        ( SELECT CHAR(10)+rtt2.name AS n FROM remont r2
                        LEFT JOIN remontCapitalChannel rt2 ON r2.id=rt2.objID
                        LEFT JOIN remontCapitalChannelTypes rtt2 ON rtt2.id=rt2.activityID
                        WHERE r2.id=r.id
                        FOR XML PATH('')
                        , TYPE
                        ).value('.', 'NVARCHAR(MAX)'), 1, 1, '')
         when 3 then STUFF(
                        ( SELECT CHAR(10)+rtt2.name AS n FROM remont r2
                        LEFT JOIN remontChannel rt2 ON r2.id=rt2.objID
                        LEFT JOIN remontChannelTypes rtt2 ON rtt2.id=rt2.activityID
                        WHERE r2.id=r.id
                        FOR XML PATH('')
                        , TYPE
                        ).value('.', 'NVARCHAR(MAX)'), 1, 1, '')
          end
         ,case remontTypeID
          when 3 then len_channel_cur
          when 2 then len_channel_cap
          when 1 then len_channel_inv
          end AS len_channel_remont
        FROM kanal obj
        LEFT JOIN linesobj l ON l.shape.STDistance(obj.shape) < 0.3
        LEFT JOIN remont r ON obj.shape.STDistance(r.shape) < 0.3
        LEFT JOIN heatPipeSections hps ON hps.lineID=l.id

        LEFT JOIN pipeSections pss ON pss.id=hps.pipeSectionID

        LEFT JOIN sortLinesForUchastok srt ON hps.pipeSectionID = srt.pipeSectionID

        LEFT JOIN nodes n1 ON n1.id = pss.nodeID1
        LEFT JOIN nodes n2 ON n2.id = pss.nodeID2


        left join externalCodes ec1 ON ec1.id = n1.externalCodeID
        left join externalCodes ec2 ON ec2.id = n2.externalCodeID
        LEFT JOIN channelType ch on ch.id = obj.channelTypeID
        LEFT JOIN overlapTypes ov on ov.id = obj.overlapTypesID
        LEFT JOIN materialTypes mt on mt.id = obj.materialTypesID
        LEFT JOIN constructionTypes ct on ct.id = obj.constructionTypesID
        WHERE NOT l.shape.STDistance(obj.shape) IS NULL
        AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
        and n1.fileID in (select value from fn_split_string(@fragment, ','))
        and (
            (@type = 'ms' and hps.magistralSite = @id)
            or (@type = 'rs' and hps.distSite = @id)
            or (@type = 'pipe' and pss.id = @id)
            or (@type = 'all')
            or (@type = 'obj' and obj.id = @id) )
    ) as t
where t.length = t.min_len and ( t.data_zaversheniya_remonta = t.last_date_remont or t.last_date_remont is NULL)
);




GO

-- Функция возвращает таблицу для паспорта Ф5
CREATE FUNCTION [dbo].[getPts_pavilion] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS  
RETURN
(
SELECT distinct
    t.tblName,
    --t.beginNode, 
    --t.endNode, 
    --IIF( t.min_node1 < t.min_node2, t.beginNode, t.endNode) as pavilion,
    t.pavilion,
    t.locationType,
    t.constructionType,
    t.s,
    t.oborudovanie_pavilona,
    t.sredstva_pozharotushenija,
    t.signalizacija,
    t.nalichie_osveshhenija,
    t.nalichie_shem_truboprovodov,
    t.god_vvoda,
    t.naimenovanie_uchastka,
    t.fio,
    t.primechanie,
    t.organizations,
    t.fileID,
    t.ms,
    t.rs,
    t.objID,
    t.length,
    t.min_len
    --MAX(count(t.objID)) OVER(PARTITION BY t.objID ) AS "max_count",
    --count(t.objID) as 'count'
    --t.pavilion_valid
     FROM (
        SELECT
        l.shape.STDistance(obj.shape) as length,        
        MIN(l.shape.STDistance(obj.shape)) OVER(PARTITION BY obj.id ) AS "min_len",
        IIF(obj.shape.STIntersects(n1.shape) = 1, IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName),IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName)) AS "pavilion",  
        --MAX(r.data_zaversheniya_remonta ) OVER(PARTITION BY obj.id ) as 'last_date_remont',       
        --MAX(CASE WHEN nn.nodeName IS NOT NULL THEN obj.id END) OVER( ORDER BY obj.id ROWS UNBOUNDED PRECEDING ) as 'pavilion_valid',
        --MIN(obj.shape.STDistance(n1.shape)) OVER(PARTITION BY obj.id ) AS "min_node1",
        --MIN(obj.shape.STDistance(n2.shape)) OVER(PARTITION BY obj.id ) AS "min_node2",
        --srt.orderID,
        'Павильон' as tblName,      
        lt.name as locationType,
        ct.name as constructionType,
        --nn.nodeName as 'pavilion',
        (vnutr_shirina_kamery * vnutr_dlina_kamery) * 1e-6 as s,
        vnutr_vysota_kamery as height,      
        oborudovanie_pavilona,
        sredstva_pozharotushenija,
        signalizacija,
        nalichie_osveshhenija,
        nalichie_shem_truboprovodov,
        god_poslednego_vvoda_v_jekspluataciju as god_vvoda, 
        IIF (ms.opisanie_uchastka_ms is not NULL, ms.opisanie_uchastka_ms, rs.naimenovanie_uchastka_rs) as naimenovanie_uchastka,
        IIF (nu_ms.fio is not NULL, nu_ms.fio, nu_rs.fio) as fio,
        n1.fileID,
        obj.primechanie,
        org.name as organizations,
        obj.id as 'objID',
        pss.magistralSite as 'ms',
        pss.distSite as 'rs'
        FROM pavilion obj       
        LEFT JOIN linesobj l ON l.shape.STDistance(obj.shape) < 0.1
        LEFT JOIN heatPipeSections hps ON hps.lineID=l.id
        LEFT JOIN pipeSections pss ON pss.id = hps.pipeSectionID

        --LEFT JOIN sortLinesForUchastok srt ON hps.pipeSectionID = srt.pipeSectionID
        LEFT JOIN nodes n1 ON n1.id = pss.nodeID1
        LEFT JOIN nodes n2 ON n2.id = pss.nodeID2
        left join externalCodes ec1 ON ec1.id = n1.externalCodeID
        left join externalCodes ec2 ON ec2.id = n2.externalCodeID       
        --LEFT JOIN nodes nn ON nn.shape.STDistance(obj.shape) < 10 
        LEFT JOIN locationTypes lt ON lt.id = obj.locationTypesID
        LEFT JOIN constructionTypes ct on ct.id = obj.constructionTypesID
        left join organizations org on org.id = obj.organizationID
        left join uchastok_ms ms ON ms.id = pss.magistralSite
        left join uchastki_ekspluatatsii ue_ms ON ue_ms.id = ms.nomer_uchastka
        left join nachalniki_uchastkov nu_ms ON nu_ms.id = ue_ms.nachalnik_uchastka
        --left join rayon_ekspluatatsii re_ms ON re_ms.id = ue_ms.rayon_ekspluatatsii
        left join uchastok_rs rs ON rs.id = pss.distSite
        left join uchastki_ekspluatatsii ue_rs ON ue_rs.id = rs.nomer_uchastka
        left join nachalniki_uchastkov nu_rs ON nu_rs.id = ue_rs.nachalnik_uchastka

        WHERE NOT l.shape.STDistance(obj.shape) IS NULL 
        and ( 
            (@type = 'ms' and pss.magistralSite = @id) 
            or (@type = 'rs' and pss.distSite = @id) 
            or (@type = 'pipe' and pss.id = @id)
            or (@type = 'all')
            or (@type = 'obj' and obj.id = @id) )
        and n1.fileID in (select value from fn_split_string(@fragment, ','))
        AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) ) 
    ) as t
where t.length = t.min_len 
--and ( t.data_zaversheniya_remonta = t.last_date_remont or t.last_date_remont is NULL)

);

GO

-- Функция возвращает таблицу для паспорта Ф6
CREATE       FUNCTION [dbo].[getPts_opora] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
    SELECT
    distinct
    t.tblName,
    t.beginNode,
    t.endNode,
    t.diameterCondit,
    t.oporaType,
    t.constructionType,
    t.kolichestvo_uporov,
    t.primechanie,
    1 as 'count_obj',
    t.orderID,
    t.id as 'id obj',
    t.ms,
    t.rs,
    t.pipeSectionID,
    t.externalLineStr,
    t.id_obj
    FROM (
        SELECT
            IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'beginNode',
            IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'endNode',
            l.shape.STDistance(obj.shape.STPointN(1)) as length,
            MIN(l.shape.STDistance(obj.shape.STPointN(1))) OVER(PARTITION BY obj.id ) AS "min_len",
            srt.orderID,
            'Опора' as tblName,
            l.externalSignLineID as 'externalID',
            obj.priznak_truboprovoda as 'externalID2',
            con_t.name as 'constructionType',
            ot.name as 'oporaType',
            obj.kolichestvo_uporov,
            hps.diameterCondit,
            obj.id,
            obj.primechanie,
            hps.magistralSite as 'ms',
            hps.distSite as 'rs',

            pss.id AS pipeSectionID,

            el.name as 'externalLineStr',
            obj.id as 'id_obj'
        FROM opora obj
        LEFT JOIN linesobj l ON l.shape.STDistance(obj.shape.STPointN(1)) < 0.3
        LEFT JOIN heatPipeSections hps ON hps.lineID=l.id
        LEFT JOIN externalSignLine el ON el.id = obj.priznak_truboprovoda

        LEFT JOIN pipeSections pss ON pss.id=hps.pipeSectionID

        LEFT JOIN sortLinesForUchastok srt ON hps.pipeSectionID = srt.pipeSectionID
        LEFT JOIN constructionTypes con_t ON con_t.id = obj.constructionTypesID
        LEFT JOIN tip_opory ot ON ot.id = obj.vid_opory

        LEFT JOIN nodes n1 ON n1.id = pss.nodeID1
        LEFT JOIN nodes n2 ON n2.id = pss.nodeID2


        left join externalCodes ec1 ON ec1.id = n1.externalCodeID
        left join externalCodes ec2 ON ec2.id = n2.externalCodeID
        WHERE NOT l.shape.STDistance(obj.shape.STPointN(1)) IS NULL
        and n1.fileID in (select value from fn_split_string(@fragment, ','))
        AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
        and (
            (@type = 'ms' and hps.magistralSite = @id)
            or (@type = 'rs' and hps.distSite = @id)
            or (@type = 'pipe' and pss.id = @id)
            or (@type = 'all')
            or (@type = 'obj' and obj.id = @id) )
        and l.externalSignLineID is not NULL
    ) as t
where t.length = t.min_len
);

GO

-- Функция возвращает таблицу для паспорта Ф7
CREATE       FUNCTION [dbo].[getPts_duker_shield_bridge] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
    SELECT
    distinct
    t.tblName as description,
    t.beginNode,
    t.endNode,
    t.length,
    t.nomer_chertezha,
    t.orderID,
    t.primechanie,
    t.fileID,
    t.obj_id
     FROM (
        SELECT
        IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'beginNode',
        IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'endNode',
        l.shape.STDistance(obj.shape) as distance,
        MIN(l.shape.STDistance(obj.shape)) OVER(PARTITION BY obj.id ) AS "min_len",
        srt.orderID,
        obj.tblName,
        obj.length,
        obj.nomer_chertezha,
        n1.fileID,
        obj.primechanie,
        obj.id as 'obj_id'
        FROM vtPassF7 obj
        LEFT JOIN linesobj l ON l.shape.STDistance(obj.shape) < 0.3
        LEFT JOIN heatPipeSections hps ON hps.lineID=l.id

        LEFT JOIN pipeSections pss ON pss.id=hps.pipeSectionID

        LEFT JOIN sortLinesForUchastok srt ON hps.pipeSectionID = srt.pipeSectionID

        LEFT JOIN nodes n1 ON n1.id = pss.nodeID1
        LEFT JOIN nodes n2 ON n2.id = pss.nodeID2

        left join externalCodes ec1 ON ec1.id = n1.externalCodeID
        left join externalCodes ec2 ON ec2.id = n2.externalCodeID
        WHERE NOT l.shape.STDistance(obj.shape) IS NULL
        AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
        and n1.fileID in (select value from fn_split_string(@fragment, ','))
        and (
            (@type = 'ms' and hps.magistralSite = @id)
            or (@type = 'rs' and hps.distSite = @id)
            or (@type = 'pipe' and pss.id = @id)
            or (@type = 'all')
            or (@type = 'obj' and obj.id = @id) )
    ) as t
where t.distance = t.min_len
);

GO


-- Функция возвращает таблицу для паспорта Ф8
CREATE      FUNCTION [dbo].[getIsolTubesPts] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS
RETURN

(
    select
        IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'beginNode',
        IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'endNode',
        l.externalSignLineID externalID,
        isolM.name as isolMaterial,
        hps.isolThickness,
        exM.name as externalMaterial,
        hps.externCoverThick,
        corM.name as anticorrMaterial,
        hps.primechanie,
        srt.orderID
    from sortLinesForUchastok srt
    left join linesobj l ON l.id = srt.lineID

    left join heatPipeSections hps ON hps.lineID = srt.lineID
    LEFT JOIN pipeSections pss ON pss.id=hps.pipeSectionID

    LEFT JOIN nodes n1 ON n1.id = pss.nodeID1
    LEFT JOIN nodes n2 ON n2.id = pss.nodeID2


    left join externalCodes ec1 ON ec1.id = n1.externalCodeID
    left join externalCodes ec2 ON ec2.id = n2.externalCodeID

    left join isolMaterials isolM ON isolM.id = hps.isolMaterialID
    left join externalMaterials exM ON exM.id = hps.externMaterialID
    left join anticorrMaterials corM ON corM.id = hps.anticorrMaterialID
    where ( (@type = 'rs' and hps.distSite = @id) or (@type = 'ms' and hps.magistralSite = @id) )
    AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
    AND (n1.fileID in (select value from fn_split_string(@fragment, ',')))
    --and l.externalSignLineID is not NULL
)

GO

-- Функция возвращает таблицу для паспорта Ф10
CREATE      FUNCTION [dbo].[getPts_remont] (@id int, @type varchar(20),@fragment varchar(max))
RETURNS TABLE
AS
RETURN
(
SELECT
    t.beginNode,
    t.endNode,
    t.remontType,
    t.remontCat,
    t.data_nachala_remonta,
    t.data_zaversheniya_remonta,
    t.otchet_po_defektu,
    t.remontTypeID,
    t.workListTube,
    t.workListChannel,
    t.workListKamera,
    t.len_tube,
    t.len_izol,
    t.len_channel,
    t.subdivision,
    t.dolzhnost,
    t.fio_otv,
    t.naimenovanie_uchastka,
    t.fio,
    t.primechanie,
    t.orderID,
    t.id as 'id_obj',
    t.length,
    t.min_len,
    t.ms,
    t.rs
    FROM (
      SELECT
      --sd.name as 'state',
      IIF (n1.nodeName is NULL or n1.nodeName = '' or n1.nodeName = ' ',n1.externalNodeName, n1.nodeName) as 'beginNode',
      IIF (n2.nodeName is NULL or n2.nodeName = '' or n2.nodeName = ' ',n2.externalNodeName, n2.nodeName) as 'endNode',
      l.shape.STDistance(obj.shape.STPointN(1)) as length,
      MIN(l.shape.STDistance(obj.shape.STPointN(1))) OVER(PARTITION BY obj.id ) AS "min_len",
      srt.orderID,
      obj.id
      ,rt.name as 'remontType'
      ,rc.name as 'remontCat'
      ,data_nachala_remonta
      ,data_zaversheniya_remonta
      ,otchet_po_defektu
      ,remontTypeID
      ,workListTube =  case remontTypeID
      when 1 then   STUFF(
                    ( SELECT CHAR(10)+rtt2.name AS n FROM remont r2
                    LEFT JOIN remontInvestTube rt2 ON r2.id=rt2.objID
                    LEFT JOIN remontInvestTubeTypes rtt2 ON rtt2.id=rt2.activityID
                    WHERE r2.id=obj.id
                    FOR XML PATH('')
                    , TYPE
                    ).value('.', 'NVARCHAR(MAX)'), 1, 1, '')
      when 2 then   STUFF(
                    ( SELECT CHAR(10)+rtt2.name AS n FROM remont r2
                    LEFT JOIN remontCapitalTube rt2 ON r2.id=rt2.objID
                    LEFT JOIN remontCapitalTubeTypes rtt2 ON rtt2.id=rt2.activityID
                    WHERE r2.id=obj.id
                    FOR XML PATH('')
                    , TYPE
                    ).value('.', 'NVARCHAR(MAX)'), 1, 1, '')
      when 3 then STUFF(
                    ( SELECT CHAR(10) + rtt2.name AS n FROM remont r2
                    LEFT JOIN remontTube rt2 ON r2.id=rt2.objID
                    LEFT JOIN remontTubeTypes rtt2 ON rtt2.id=rt2.activityID
                    WHERE r2.id=obj.id
                    FOR XML PATH('')
                    , TYPE
                    ).value('.', 'NVARCHAR(MAX)'), 1, 1, '')
      end
      ,workListChannel =  case remontTypeID
      when 1 then STUFF(
                    ( SELECT CHAR(10)+rtt2.name AS n FROM remont r2
                    LEFT JOIN remontInvestChannel rt2 ON r2.id=rt2.objID
                    LEFT JOIN remontInvestChannelTypes rtt2 ON rtt2.id=rt2.activityID
                    WHERE r2.id=obj.id
                    FOR XML PATH('')
                    , TYPE
                    ).value('.', 'NVARCHAR(MAX)'), 1, 1, '')
      when 2 then   STUFF(
                    ( SELECT CHAR(10)+rtt2.name AS n FROM remont r2
                    LEFT JOIN remontCapitalChannel rt2 ON r2.id=rt2.objID
                    LEFT JOIN remontCapitalChannelTypes rtt2 ON rtt2.id=rt2.activityID
                    WHERE r2.id=obj.id
                    FOR XML PATH('')
                    , TYPE
                    ).value('.', 'NVARCHAR(MAX)'), 1, 1, '')
     when 3 then STUFF(
                    ( SELECT CHAR(10)+rtt2.name AS n FROM remont r2
                    LEFT JOIN remontChannel rt2 ON r2.id=rt2.objID
                    LEFT JOIN remontChannelTypes rtt2 ON rtt2.id=rt2.activityID
                    WHERE r2.id=obj.id
                    FOR XML PATH('')
                    , TYPE
                    ).value('.', 'NVARCHAR(MAX)'), 1, 1, '')
      end
      ,workListKamera = case remontTypeID
      when 1 then   STUFF(
                    ( SELECT CHAR(10)+rtt2.name AS n FROM remont r2
                    LEFT JOIN remontInvestKamera rt2 ON r2.id=rt2.objID
                    LEFT JOIN remontInvestChannelTypes rtt2 ON rtt2.id=rt2.activityID
                    WHERE r2.id=obj.id
                    FOR XML PATH('')
                    , TYPE
                    ).value('.', 'NVARCHAR(MAX)'), 1, 1, '')
      when 2 then   STUFF(
                    ( SELECT CHAR(10)+rtt2.name AS n FROM remont r2
                    LEFT JOIN remontCapitalKamera rt2 ON r2.id=rt2.objID
                    LEFT JOIN remontCapitalChannelTypes rtt2 ON rtt2.id=rt2.activityID
                    WHERE r2.id=obj.id
                    FOR XML PATH('')
                    , TYPE
                    ).value('.', 'NVARCHAR(MAX)'), 1, 1, '')
      when 3 then STUFF(
                    ( SELECT CHAR(10)+rtt2.name AS n FROM remont r2
                    LEFT JOIN remontKamera rt2 ON r2.id=rt2.objID
                    LEFT JOIN remontChannelTypes rtt2 ON rtt2.id=rt2.activityID
                    WHERE r2.id=obj.id
                    FOR XML PATH('')
                    , TYPE
                    ).value('.', 'NVARCHAR(MAX)'), 1, 1, '')
      end
      ,case remontTypeID
      when 3 then len_tube_cur
      when 2 then len_tube_cap
      when 1 then len_tube_inv
      end AS len_tube
      ,case remontTypeID
      when 3 then len_izol_cur
      when 2 then len_izol_cap
      when 1 then len_izol_inv
      end AS len_izol
      ,case remontTypeID
      when 3 then len_channel_cur
      when 2 then len_channel_cap
      when 1 then len_channel_inv
      end AS len_channel
      ,subd.name as subdivision
      ,d.znachenie as dolzhnost
      ,nach.fio as fio_otv
      ,IIF (ms.opisanie_uchastka_ms is not NULL, ms.opisanie_uchastka_ms, rs.naimenovanie_uchastka_rs) as naimenovanie_uchastka
      ,IIF (nu_ms.fio is not NULL, nu_ms.fio, nu_rs.fio) as fio
      ,obj.primechanie
      ,hps.magistralSite as 'ms'
      ,hps.distSite as 'rs'
FROM remont obj
LEFT JOIN linesobj l ON l.shape.STDistance(obj.shape.STPointN(1)) < 0.3
LEFT JOIN heatPipeSections hps ON hps.lineID=l.id

LEFT JOIN pipeSections pss ON pss.id=hps.pipeSectionID

LEFT JOIN sortLinesForUchastok srt ON hps.pipeSectionID = srt.pipeSectionID

 LEFT JOIN nodes n1 ON n1.id = pss.nodeID1
 LEFT JOIN nodes n2 ON n2.id = pss.nodeID2



left join externalCodes ec1 ON ec1.id = n1.externalCodeID
left join externalCodes ec2 ON ec2.id = n2.externalCodeID
LEFT JOIN stateDefect sd ON sd.id = obj.stateID
LEFT JOIN remontCat rc ON rc.id = obj.remontCatID
LEFT JOIN remontTypes rt ON rt.id=remontTypeID
LEFT JOIN nachalniki_uchastkov nach ON nach.id=obj.responsibleID
LEFT JOIN dolzhnosti d ON d.id=nach.dolzhnost
LEFT JOIN subdivisions subd ON subd.id=subdivisionID
left join uchastok_ms ms ON ms.id = hps.magistralSite
left join uchastki_ekspluatatsii ue_ms ON ue_ms.id = ms.nomer_uchastka
left join nachalniki_uchastkov nu_ms ON nu_ms.id = ue_ms.nachalnik_uchastka
--left join rayon_ekspluatatsii re_ms ON re_ms.id = ue_ms.rayon_ekspluatatsii
left join uchastok_rs rs ON rs.id = hps.distSite
left join uchastki_ekspluatatsii ue_rs ON ue_rs.id = rs.nomer_uchastka
left join nachalniki_uchastkov nu_rs ON nu_rs.id = ue_rs.nachalnik_uchastka
--left join rayon_ekspluatatsii re_rs ON re_rs.id = ue_rs.rayon_ekspluatatsii
WHERE NOT l.shape.STDistance(obj.shape.STPointN(1)) IS NULL
        and n1.fileID in (select value from fn_split_string(@fragment, ','))
        AND ( (not ec1.name in ('П1','П2') or not ec2.name in ('П1','П2')) or (ec1.name is null AND ec2.name is null) )
        and (
                (@type = 'ms' and hps.magistralSite = @id)
                or (@type = 'rs' and hps.distSite = @id)
                or (@type = 'pipe' and pss.id = @id )
                or (@type = 'all')
            )
) t
where t.length = t.min_len
);

GO




